//! The offline manual and widget descriptions share these reviewed definitions.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Topic {
    Setup,
    Recording,
    Editing,
    Mixing,
    Dj,
    Controllers,
    Emergency,
    Projects,
    Offline,
}
impl Topic {
    pub const ALL: [Self; 9] = [
        Self::Setup,
        Self::Recording,
        Self::Editing,
        Self::Mixing,
        Self::Dj,
        Self::Controllers,
        Self::Emergency,
        Self::Projects,
        Self::Offline,
    ];
    pub fn title(self) -> &'static str {
        match self {
            Self::Setup => tr!("Audio setup"),
            Self::Recording => tr!("Record a held note"),
            Self::Editing => tr!("Edit and undo"),
            Self::Mixing => tr!("Mix a session"),
            Self::Dj => tr!("Prepare a DJ deck"),
            Self::Controllers => tr!("Connect a controller"),
            Self::Emergency => tr!("Stop and recover"),
            Self::Projects => tr!("Save and reopen"),
            Self::Offline => tr!("Offline operation"),
        }
    }
    pub fn text(self) -> &'static str {
        match self {
        Self::Setup => tr!("Start with the output quiet. Audio devices and latency reports the backend-accepted logical output, observed callback sizes and active project routing; physical negotiated rate and converter latency are unavailable through CPAL. Projects without explicit routing use outputs 1/2, mono sums them, and additional outputs are silent. Audio routing defines stable mono/stereo/multichannel aliases, independent tracks, buses, deck taps and record sources. Review and confirm changes while stopped; Save and Open retain them. Physical channel meters and quiet channel tests help verify connections. Live inputs require separate preview and confirmation. Linux profiles support ALSA and an existing JACK server, including PipeWire through its JACK library. The graph server owns rate, quantum and scheduling. Named graph ports and exact saved links appear after profile discovery; missing endpoints stay disconnected until they return. Rate changes and server loss retain the project for explicit stopped reconnect. Graph outputs do not run the ALSA physical loopback probe. Settings profiles separate saved preferences from running audio: Apply and save persists audio choices without changing the stream. Preview saved audio, Use saved audio now, then Stop and change output explicitly stops performance and changes the stream, or restart to use the saved setup. A failed change restores the prior output when possible; if rollback also fails, the retained session can still Save, New/Open and Close. Playback never resumes automatically. Optional Measure loopback requires a suitable line-level cable/interface route and explicit confirmation; it reports qualified host callback-to-callback return timing only after three reliable probes, not physical converter roundtrip. Cancellation, missing loopback and corrupt evidence produce no current measurement. The main mixer is stereo; independent routing can address additional physical outputs. Headphone monitoring uses a chosen separate stereo output; it never replaces the main mix. Select cues, blend cue/master, set level and optional split cue in Audio routing. Load a built-in stem, play it, then verify sound at your physical output. Connection and meter evidence cannot prove that speakers or headphones are audible."),
        Self::Recording => tr!("Choose an empty clip cell and use its Arm compose action (Shift-click or Shift+F10), or Arm selected cell. The armed destination is displayed above the sampler and stays fixed while browsing. Choose Keys, Analog or Pad; hold a pad and release it to record its actual duration. Stopped composition starts at local beat zero. Playing clips capture launch-relative positions. Disarm finalizes captures; Stop also disarms. Launch the resulting clip to hear it later. This is MIDI/pad note capture, not microphone or external audio recording. Open Piano roll on the selected empty or MIDI cell to draw, select, move, resize, transpose, duplicate, mute or delete notes. Apply commits one captured-target MIDI edit; Cancel preserves the current clip. Triplet/free grids, numeric clip/loop bounds and note values, scale folding, zoom and scroll are available. Audition is independent and never records."),
        Self::Editing => tr!("Open a clip's alternate actions and choose Edit clip gain. Gain changes future note onsets; already held notes retain their onset gain. Use Edit → Undo / Redo, or the active shortcut bindings, to compare. A continuous slider gesture is one named history entry. History is bounded; admission failures or truncation are shown explicitly. Transport and physical held gates are not creative edits. Piano roll offers note drawing, pointer/keyboard edits and explicit clip/loop ranges with stable note identities. It uses the same session History after Apply. This build offers frame-based picture placement alongside Session transport; it does not offer an Arrange timeline, warp editor, automation lanes or plugins."),
        Self::Mixing => tr!("Launch a scene, then adjust a track's gain. Track headers toggle mute; alternate actions provide solo and its effect rack. Muted tracks keep advancing, so unmuting returns to the current musical position. Scene effects process track audio assigned to that scene; monitoring and tails follow the track’s scene bus. Master effect slots process the stereo bus. Observe meters and callback diagnostics while adding load. Render CPU, callback elapsed time and UI frame time are different measurements; deadline overruns are not a backend XRUN count."),
        Self::Dj => tr!("Select a crate row and explicitly load A or B. Built-in Drums (session) and Harmony (session) work without media files. Wait for Loaded: Queued only confirms admission. The filename BPM/key hints and heuristic analyzed BPM have distinct provenance and are not a verified beat grid. Use the grid editor to set the downbeat, slip beat lines, stretch tempo or correct half/double ambiguity in a draft preview. Apply creates one manual uniform four-beat grid; it does not overwrite analyzed BPM or move cues. Cancel or Escape discards unapplied drafts. Set a main cue or hot cues, set loop in/out, then audition. Pitch lock separates pitch from tempo. Match follows the crossfader-favored deck's effective tempo. Remaining time is an estimate and repeating loops suppress runout alerts. Preparation persists in the library for the exact file identity."),
        Self::Controllers => tr!("Open the MIDI window and Retry / rescan MIDI. Settings can request all inputs, selected exact port names or disabled inputs. Check requested versus applied policy and per-port errors before playing. The native callback only queues bounded input; overflow releases that source's gates and reports counters. Factory profiles and the original NS7 bridge have separate compatibility receipts; a matching device name is not physical compatibility proof. NS7II remains unverified. MIDI clock input is an observable tick hook, not tempo synchronization or clock output. MIDI Learn captures and reviews compatible controls; named mapping presets save and transfer their factory overrides with explicit exact-port activation."),
            Self::Emergency => tr!("Enable performance mode to protect playing/touched deck replacement, destructive edits and project/device changes across GUI, MIDI and IPC. Continuous mixing, live composition/recording, stopped-deck loads and Save remain available; optional scans/imports/analysis/theme/export work is refused or deferred. Safe stop deliberately stops the session and both decks, finalizes held captures and releases input notes; finite sample and effect tails continue naturally. Emergency silence additionally fades output to latched mute over 2 ms. Wait for renderer acknowledgment: request acceptance is not silence. Release physical keys, pads and touches, then explicitly acknowledge input recovery. This is your report, not a hardware health check. Emergency mute remains until a deliberate stopped DSP reset through the audio owner; a two-second −80 dBFS tail observation cannot prove bypassed/delayed history is empty. Failed reset keeps mute; you can acknowledge inputs and remain muted to Save and deliberately leave protection or close. No action automatically resumes playback. Ordinary Session Stop retains its narrower session-only behavior. Read Diagnostics queue/reset counters and explicit failures before recovery; physical hardware QA remains separate."),
        Self::Offline => tr!("Omatainer starts without an account or cloud session. Locally available media, native projects with embedded PCM, user sampler banks, built-in instruments/effects, Help and license notices work locally. Reusable bank definitions reference local sources: retain those files or use a verified library relocation; missing sources remain explicit. Native projects embed their playable audio. Free To Use search and licensed non-premium previews require explicitly enabled internet access. Provider offline storage is unavailable. Audio plugin hosting, cloud transfer, account authentication and credential storage are not implemented. No account tokens are collected. Preferences, project envelopes and support reports reject unknown credential fields; project names, paths and audio are intentional user content, not redacted documents. Support export is a reviewed local file with an allowlisted schema, never an upload. License Source record links explicitly hand off to an external browser; that browser and host Unix proxies are outside the network-denied application test. Network filesystems, remote display/audio servers and source-build package downloads also need their own availability. Safe mode starts stopped without audio/MIDI devices; it can Open, Recover and Save locally. Network-denied fixtures qualify local software paths, not physical controllers, OS audio dropouts or perceived quality."),
        Self::Projects => tr!("Project → New, Open and window close protect unsaved work with Save changes / Discard changes / Cancel. Save project as chooses a .omat path; replacing an existing file requires the checkbox. Save copy leaves the current path and unsaved baseline unchanged. Native projects embed playable media and creative state. Reopen restores playback stopped and excludes physical held keys, connections and DSP tails. Later edits during saving remain dirty. Cancel before commit preserves the old document; a completed commit is reported honestly. Autosave and recovery keeps separate full edit-state batches about every two seconds and compacts checkpoints at the saved profile interval. Capture and disk delays can increase the loss window; read the last confirmed durable age. At restart, preview an inactive recovery and restore as a stopped, unsaved untitled copy without overwriting the original saved version. Full storage stops new writes visibly while preserving existing recovery. Project dependencies checks every embedded source and unavailable device; moved sources require explicit verified choices. Portable project lists samples, saved device and preset identities, retained application dependency notices and unverified audio rights. Export includes all embedded PCM and copies only explicitly selected originals into one checksum-verified .ompack archive. Import verifies and prepares the session in a new folder, refuses existing destinations, and rebinds collected originals locally. Opening the imported session stays stopped and uses the unsaved-work guard. Use a private test destination for the guided example."),
    }
    }
}

pub(crate) struct Definition {
    pub title: &'static str,
    pub units: &'static str,
    pub purpose: &'static str,
    pub topic: Topic,
}
macro_rules! controls { ($( $id:ident, $title:literal, $units:literal, $purpose:literal, $topic:ident; )*) => {
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub(crate) enum Control { $( $id, )* }
    impl Control {
        pub const ALL: &'static [Self] = &[ $(Self::$id,)* ];
        pub fn definition(self) -> Definition { match self { $( Self::$id => Definition { title: tr!($title), units: tr!($units), purpose: tr!($purpose), topic: Topic::$topic }, )* } }
    }
}}
controls! {
    Arrangement, "Arrange a song", "Shared sources and independent musical-beat placements", "Open Arrangement timeline in Setup. Retain a reviewed Session audio or MIDI clip, choose a destination track and place it at the selected range start or double-click an empty track row. Copies share source audio and keep independent start, offset, duration, repetition and gain. Drag to move; Shift-drag trims the end. Use exact beat fields, snap, zoom, selected range and the overview for long songs. The instance chooser includes placements whose track was deleted; choose a destination and move the instance to recover it. Review Use Arrangement playback and Apply with transport, decks and recording stopped in Studio mode. Apply creates one Undo entry. Play, Pause, Rewind and Seek range start use the actual transport and tempo map; the playhead follows the renderer. Save keeps sources and instances, and selected-track imports copy their song placements. Export audio offers Arrangement using the same renderer. Audio pitch resampling changes pitch and duration; independent time stretching is separate.", Editing;
    ClipManager, "Manage Session clips", "Create, organize and reuse complete clip content", "Open Session clips in Setup or the clip grid alternate Manage clip action. Choose source and destination by track and scene. Create MIDI clips with Ctrl+N or use Edit or import audio for audio sources. Rename, disable or choose an exact RGB color and commit properties with Ctrl+Enter. Ctrl+D duplicates with fresh note identities; Ctrl+M moves the original content; Ctrl+Shift+Backspace deletes. Copy and move require an empty destination and retain notes, lanes, regions, gain, reverse, loop and color settings. MIDI uses the destination track instrument and routes; audio shares immutable PCM. Stop affected clips and recording before applying in Studio mode. Every edit is one atomic Undo operation. Save a new .omatclip preset with Ctrl+Shift+S; existing files are preserved. Inspect with Ctrl+O, insert into an empty destination and audition through its normal instrument and mixer, then stop its track. Presets embed up to 128 MiB audio and preserve complete clip settings. Refresh after another project edit before audition or apply. Source files stay intact.", Editing;
    AudioClip, "Edit Session audio clips", "Source frames, tempo, pitch, reverse, gain and loops", "Choose an empty or audio slot, then open Audio clip in Setup or use the clip's alternate audio action. Inspect a supported local file or reuse a shared project source. Review the rainbow waveform, zoom and source scroll; trim and loop bounds use exact half-open source frames. Pitch resampling changes pitch and duration; source tempo places the audio against the musical clock. Gain, reverse and source settings are nondestructive. Stop the target clip and recording and use Studio mode before Apply. A bounded worker decodes and prepares the edit; the renderer acknowledges one complete Undo entry. Stale targets preserve current work. Save retains the embedded shared source and all settings. Older clips keep whole-buffer stretching until explicitly converted by Apply. Use Arrangement timeline in Setup to retain a reviewed clip as a shared song source and place independent instances on tracks.", Editing;
    MidiControllers, "MIDI controller lanes", "Wire channels 1–16; CC/pressure 0–127; pitch bend 0–16383", "Open MIDI controller lanes in the piano roll. Choose channel and lane, enter an exact musical beat and value, then Insert controller point. Select a point in the plot or list to change or delete it. Save device label names a controller or a specific bank/program patch. Bank/program insertion sends CC 0 MSB, CC 32 LSB, then the two-byte Program Change. Pitch bend center is 8192. Apply prepares source ticks on a worker, commits one Undo entry and saves labels in project schema 15. Seek and launch restore earlier scalar controllers and the last patch before active notes. Stop releases owned notes/pedals and restores another managed owner's bend, pressure, modulation, breath or expression on a shared channel; otherwise those controls return to neutral. Volume, pan, arbitrary CC and patch selection retain their values. Imported RPN/NRPN/data-entry/channel-mode transactions retain normal playback/export but are not inferred during seek. Dense output still uses the existing 256-event block refusal limit.", Editing;
    PrepareQueue, "Prepare upcoming tracks", "4096 tracks and 2 MiB of captured references", "Queue a selected track or filtered crate while other decks play. Reorder or remove upcoming tracks, load their captured file version through ordinary deck protection, and preview a loaded paused deck on its existing output. Stop preview restores its position. Remove-after-play requires a complete 10 ms window of confirmed digital main output from a playing deck; loads, paused previews, silence and uncertain measurements retain tracks. Retain keeps them until manual removal. Save creates one ordered manual crate; explicit restore uses its current catalog versions. Shift with deck A Load queues the selected track; shift with deck B Load queues the published filtered crate on profiles with those controls. Physical controller mappings still need device validation.", Dj;
    LibraryHealth, "Library media health", "Captured read-only validation; at most 4096 rows per queue", "Validate a selected row or the filtered crate without replacing live decks. The existing decoder worker reads each complete file and discards packet PCM. Status distinguishes missing, unreadable, unsupported, corrupt and changed sources. Read-only audio remains playable and uses sidecar preparation. Bad tags are reported separately when audio still decodes. Results describe the last checked version; rescan and validate after media changes. Cancel stops remaining work; earlier results stay visible. Performance protection or an explicit media load stops validation. Closing the panel leaves an active queue running.", Dj;
    PreferenceLanguage, "Interface language", "English, Español or Deutsch; saved per profile", "Select the display language for this profile. Preview and Cancel retain the applied language; Apply saves it and changes labels on the next frame. Musical values and stored names/paths remain unchanged. Advanced text without a translation uses English. Mixed-direction shaping is limited by the native renderer.", Setup;
    PreparationLocks, "Preparation locks", "Reviewed grid, BPM and metadata protection", "Capture current library versions, select lock fields, Review and Save. Grid locks prevent manual grid edits and Undo until unlocked. BPM and metadata locks exclude automatic replacement, including forced analysis and tag refresh. Reviewed manual tag edits remain available; unselected locked fields stay intact. Preview analysis replacements in the analysis panel and actual tag refresh replacements in the tag editor before refreshing. Locks are catalog sidecars and survive restart. Replacement content starts with fresh preparation.", Dj;
    TrackAnnotations, "Track ratings, colors and annotations", "Stable track metadata; ratings 0–5", "Capture selected or filtered stable IDs, select changed fields, Review and Apply. Ratings, colors, groups, tags and multiline notes are stored in library metadata; audio bytes and loaded sound are unchanged. Unselected fields preserve each track’s own values. Search also matches annotations; explicit filters include rating>=4, tag:clean, color:#FF6600, group:peak and note:request. Cancel can stop a pending write before its publication claim; closing keeps admitted writes running.", Dj;
    SmartCrates, "Smart crate rules", "All or Any typed conditions; inclusive numeric ranges", "Select an empty named crate and open Smart crate rules. Choose supported text, key, BPM, duration, rating or confirmed-played conditions. Preview current results before Save. Membership is updated on the catalog worker when current metadata changes. Refresh recomputes saved membership explicitly. Cancel stops a preview without saving; Remove leaves an empty manual crate.", Dj;
    TrackAnnotationRule, "Automatic annotation crate rules", "Saved predicates over current library annotations", "Select an empty named crate, choose minimum rating, optional color, group substring, exact tag and notes substring, then save its rule. Conditions combine and membership updates with annotations after reload or restart. Manual member edits are unavailable on a rule crate. Removing the rule leaves an empty manual crate; populated manual crates are protected from conversion.", Dj;
    VideoImport, "Import local picture", "FFmpeg/ffprobe; supported constant frame rates", "Import one local SDR video after checking every decoded timestamp. Variable rate, rotation, unsupported codecs or missing tools produce an error. Audio from the picture is excluded. Save the native project to retain its external picture reference.", Editing;
    VideoPreview, "Picture preview", "Resizable native preview and detached viewport", "Picture follows the per-callback audio seconds clock. A saved preview latency adjustment (-2000 to 2000 ms; negative delays picture) can account for audio hardware; it does not shift exports. Outside trim is black; decoder latency shows a waiting frame rather than stale picture. Performance protection suspends optional decoding.", Editing;
    VideoPlacement, "Picture trim and placement", "Zero-based video frames; exclusive trim end", "Apply a valid source trim and project placement. Timecode offset is signed frames; 29.97 and 59.94 support drop-frame timecode. Seek ends clip recording and releases clip notes while preserving physical input ownership.", Editing;
    VideoLocator, "Picture locators", "128 named project-frame locators", "Add or seek saved frame positions. Names contain 1–128 control-free UTF-8 bytes. Native project reopen verifies the same picture source before decoding.", Editing;
    VideoRender, "Render selected scene against picture", "New output folder; 48 kHz stereo float score", "Render the selected Session scene from project zero with fresh DSP state, including native mixer/effects. Publish score.wav, lossless FFV1/PCM picture.mkv and alignment.json together. Picture audio is excluded. WAV is limited to 2 GiB; source and live project remain intact.", Editing;
    MicAux, "Mic and auxiliary mixer", "Reviewed live inputs, independent mixes and deliberate talkover", "Open Mic & aux and review retained aliases. Select a mono or stereo input, then master, booth and raw recording mixes independently. New sources start muted. Stop playback and recording and use Studio mode before applying or removing selection. Use Audio routing to enable the intended native input; this panel never opens a device. Live gain, mute, optional three-band tone and talkover remain available in Performance Mode. Talkover offers a voice threshold, attenuation, attack/release and automatic, held or bypassed ducking. Source changes fade out before the new source fades in. Meters show source availability and decaying input/output peaks. Final-output recording includes the actual audience mix; select a raw recording alias for independent voice exclusion. Save and History retain controls; foreign selective imports keep the current external-source choices.", Offline;
    AudioExport, "Export master audio", "Reviewed scene/session range, repeats, tails and delivery format", "Open Audio export & recording, review the source, then choose the currently launched session or a scene. Ranges begin at the captured cursor or scene zero. Choose an exact program alias for routed projects, mono/stereo, rate, integer dither and optional peak normalization. Preroll rebuilds effects; repeated ranges copy the same audio and release sources once before the final tail. Native float32/PCM16/PCM24 WAV works without a codec tool; FLAC16/FLAC24/320 kbps MP3 requires FFmpeg. Physical input routes require real-time recording. A cancellable worker publishes a new folder only when rendering and encoding finish; existing outputs and live playback stay intact.", Offline;
    PerformanceRecording, "Record a performance", "Exact final output or raw routed return; bounded WAV segments", "Review the source in Audio export & recording, choose an exact source alias, format, duration and new folder, then start recording. Final outputs include the limiter, output conversion and recovery fades; raw record aliases keep their selected tap and channel order. Recording works during Performance Mode and does not change Auto monitoring for a final-output capture. Native files split at 256 MiB. Stop or source loss finalizes the valid prefix and reports missing frames or disk errors. FLAC/MP3 encoding follows capture and retains original WAV files. Existing folders are never replaced. Review an interrupted recording folder, then recover its exact unchanged WAV prefixes; active files, foreign headers, linked files and changed reviews are refused.", Recording;
    VideoCancel, "Cancel video work", "Pending decoder or render", "Stop and reap the owned decoder on its worker. Cancellation before publication removes staging output. A directory already published retains its committed result. Existing output folders are never overwritten.", Editing;
    MusicProvider, "Licensed music providers", "Explicit non-commercial consent; one original-pitch preview", "Enable the public Free To Use API only after accepting its current non-commercial license and attribution requirement. Search current metadata, copy credits and preview non-premium music. Premium and commercial use need a paid license for this app; none is configured. The adapter supports no offline storage, stems, recording, export or DJ decks. Close or Stop cancels preview audio. Network and decoding run on a bounded worker; safe and performance modes block these jobs.", Dj;
    AudioRouting, "Audio routing", "Saved aliases and explicit channel maps", "Inspect and edit project routes for tracks, scene effects, decks, buses, inputs, outputs and record sources. Choose pre FX, post FX or post mixer taps. Missing physical channels stay silent; cycles, invalid maps and changed project revisions reject the entire draft. Stop transports before confirmation. Apply is undoable and saved with the project. The pinned Linux backend advertises up to 32 live channels; saved addresses through 64 remain available for absent-channel preservation.", Setup;
    AudioRoutingInput, "Live routed input", "Exact device at the active output nominal rate", "Saved input choices never open automatically. Preview fresh advertised capabilities, then explicitly stop and enable input. A bounded cushion waits for two actual callback blocks before delivering input; its frame count and nominal buffering target are shown. Startup silence, later missing frames, source discontinuities and overflow have separate counters. Input/output blocks above 2730 frames are refused. Faults, missing callbacks and output changes disable input and require fresh confirmation. Separate device clocks are not resampled. Safe mode disables device access.", Setup;
    AudioRoutingRecord, "Capture a record source", "1–26 channels; float WAV; 128 MiB maximum", "Apply and refresh routes, choose a record alias and new WAV path, then capture on a worker. Stop keeps completed audio; Cancel removes the partial file. Missing frames, overflow, invalid samples and file failures prevent incomplete publication. Existing files are preserved. Routing, project, audio and emergency-stop changes finish the current capture.", Recording;
    AudioRoutingTest, "Test a physical output", "One second at −40 dBFS; stopped transports", "Play a ramped 997 Hz tone on one active physical channel. Starting playback, cancellation or performance protection ends it. The tone and every independently routed output obey emergency silence. Digital meters and private software loopback do not prove hardware converter or interface behavior.", Setup;
    InputMonitoring, "Audio input monitoring", "In / Auto / Off; Arm; Cue", "In hears routed audio and suppresses audio-clip playback. Auto hears input on an armed track while no clip is sounding or a recording is active. Off hears clips and removes software input monitoring for direct hardware monitoring. Pending launches keep input until onset. Migrated tracks retain their additive route until a mode is chosen; new and duplicated tracks use Auto, disarmed. Imported tracks use Off because external input routes are excluded. Audio routing chooses exact input and record aliases and shows the input cushion, gaps and availability. Monitoring changes never open devices or change raw input recording. Cue selects this track's post-effect, pre-fader signal in the separate headphone PFL bus. Arm and mode persist with project state and Undo; Cue is transient. Input buffering and effects add latency; complete graph compensation is separate.", Setup;
    Headphones, "Headphone mixing", "Independent stereo output, level and cue/master blend", "In Audio routing, choose a stereo headphone output alias and review/apply the stopped routing draft. Headphone channels cannot overlap any program route. Missing channels stay silent. Select PFL to hear selected tracks before channel gain and selected decks before channel and crossfader gains, or deck A/B to retain the original NS7 front-panel policy. Cue/master blend affects PFL headphones only; main stays unchanged. Split cue folds selected cue to the left and master to the right at half the stereo sum. Level and source changes ramp over five milliseconds. Quiet left/right checks run for one second only while stopped on an available pair; playback, route/project/output changes, cancellation and emergency stop retire them. Digital availability and meters do not prove physical sound.", Setup;
    AutomationOpen, "Automation API", "Versioned local and loopback control", "Inspect the private local socket, stable session IDs and API results. Command acceptance is pending until its job reports applied. The native inspector uses the same typed API as scripts.", Setup;
    AutomationState, "Read API state", "Stable IDs and reviewed revision", "Read a bounded state page from automation version 1. Names may be shortened here; native project data stays complete.", Setup;
    AutomationSchedule, "Schedule API action", "Absolute quarter-note beat", "While transport plays, schedule selected-track gain on a future musical beat. Stops, safety changes and project replacement invalidate pending actions. Audio executes from fixed storage without network IO.", Setup;
    AutomationGain, "Scheduled API gain", "0–1.5", "Choose the selected track gain for an explicitly submitted future action. Moving this slider does not change audio.", Setup;
    AutomationBeat, "API action beat", "Absolute quarter-note beat", "Choose a future beat within 16384 quarter notes. Next beat fills a conservative upcoming boundary; past or stopped-transport scheduling is rejected.", Setup;
    AutomationRename, "API track name", "Atomic reviewed edit", "Rename the selected native track through the version-1 API using its stable ID and the displayed project revision. Stale concurrent edits reject; an applied rename is undoable.", Setup;
    AutomationJob, "Refresh API job", "Pending/applied/rejected/cancelled", "Read the last submitted job. Receipts survive controller reconnect while retained in this launch. Pending jobs are never evicted; completed results may expire as new jobs arrive.", Setup;
    AutomationCancel, "Cancel API job", "Before audio claims the commit", "Cancel a pending job atomically. Completed or claimed commits refuse cancellation rather than reporting an undo.", Setup;
    AutomationToken, "Show OSC access token", "Current loopback adapter only", "Reveal the current 128-bit access token for an explicitly enabled loopback client. It changes after disable/re-enable or app restart and is never saved in preferences.", Setup;
    AutomationOscEnable, "Enable loopback OSC", "127.0.0.1 UDP; saved profile", "Preview and Apply explicitly to enable the authenticated OSC adapter. It binds only loopback, requires the current token and carries typed API JSON in an OSC blob. No LAN listener is opened. Cancel preserves the live listener.", Setup;
    AutomationOscPort, "OSC port", "0 automatic; otherwise 1024–65535", "Save the loopback UDP port. Bind failure reports the error and preserves the previous listener. The actual selected port is shown in Automation.", Setup;
    AutomationRetry, "Retry OSC settings", "Saved intent versus actual listener", "Retry the saved listener intent after a bind or worker failure. Existing live configuration remains until a replacement is ready.", Setup;
    DisplayLayout, "Compact control menus", "Small viewports and large text", "Safety (Guard, STOP or MUTE when active), File, Setup and FX menus retain the full controls in scrollable menus when four toolbar rows would crowd the performance surface. Tab focus scrolls performance controls into view. Use Setup or Ctrl+, for Preferences.", Offline;
    DisplayContrast, "Display contrast", "Desktop, dark or light palette", "Choose a high contrast palette for dark rooms or bright stages. State cues use text and shapes as well as color. Preview and Apply save the choice; Cancel keeps the current display.", Offline;
    DisplayMotion, "Reduced motion", "Decorative animation", "Stop decorative platter rotation and UI transitions while retaining live transport values, waveform positions and audio. No playback command is sent.", Offline;
    DisplayWaveform, "Waveform contrast", "1 = original paint; 3 = foreground", "Raise trace visibility without changing audio amplitude, seek positions or waveform geometry.", Dj;
    DisplayLevel, "Level contrast", "1 = original paint; 3 = foreground", "Raise the visibility of the smoothed signal activity strip. It is not a calibrated peak, loudness or clipping measurement; changing its contrast does not change audio.", Dj;
    TemplateOpen, "Templates", "Native editable templates", "Open native project and track templates. New template files and duplicates never replace an existing file.", Projects;
    ProjectVersionsOpen, "Project versions", "Named snapshots and alternatives", "Save a named snapshot with revision notes and shared immutable audio. Compare tracks, clips, routing and devices before restoring an unsaved copy or branching a new project. Preview unreferenced assets before pruning.", Projects;
    ProjectImportOpen, "Project import", "Reuse selected project material", "Browse a native project, select tracks and scenes, review timing and device conflicts, then apply one undoable import. Source files and existing tracks remain intact.", Projects;
    TemplatePath, "Template file paths", "Native editable templates", "Choose an absolute .omtemplate file, a new backup archive or a new import folder.", Projects;
    TemplateSave, "Save template", "Native editable templates", "Capture project state or selected-track devices and routing. Track templates exclude notes, clips and launch state.", Projects;
    TemplateInspect, "Inspect template", "Native editable templates", "Validate the native file and retain its exact fingerprint, dependency manifest and desired hardware names.", Projects;
    TemplateUse, "Use template", "Native editable templates", "Create a fresh stopped unsaved project, or replace only selected-track configuration. Track application preserves music, stops playback and resets undo history. Hardware requires separate explicit review.", Projects;
    TemplateDuplicate, "Duplicate template", "Native editable templates", "Write a new named template without changing the source file or active session.", Projects;
    TemplateHardware, "Review template hardware", "Native editable templates", "Copy exact requested endpoints into Preferences draft. Preview and Apply explicitly; Cancel preserves current connections. Missing or ambiguous ports are reported without substitution.", Projects;
    TemplateBackup, "Template backup and import", "Native editable templates", "Export embedded playable audio and metadata in a checksum-verified portable archive. Import into a new folder; existing destinations are refused.", Projects;
    TemplateCancel, "Cancel template operation", "Native editable templates", "Cancel before publication or commit to preserve existing files and the current session. Completed publication is reported honestly.", Projects;
    TemplateStartup, "Startup session", "Native editable templates", "Choose Demo, Empty or a native project template for next launch. Invalid templates preserve settings and offer an explicit empty session for this launch. Hardware remains on the active profile until reviewed.", Projects;
    PortableOpen, "Portable project", "Native session and dependency manifest", "Open the portable project workflow or a published imported session. Opening a session uses the existing unsaved-work guard and never starts playback automatically. Global device preferences and mappings are unchanged.", Projects;
    PortableInspect, "Inspect portable dependencies", "Every sample and device/preset identity", "Capture the native session, verify external sources and list every embedded sample, saved device ID and preset/settings checksum. Application dependency records and full distribution notices are retained in the archive. External audio and plugin redistribution rights remain unverified; no plugin binary is copied.", Projects;
    PortableCollect, "Collect original source", "One explicit selection per asset", "Choose a verified original source to copy into the archive under a relative SHA-256 filename. All embedded audio is included regardless of selection. Selected original reads are limited to 1 GiB; duplicate bytes occupy one archive entry. Originals are never changed.", Projects;
    PortablePath, "Portable project paths", "Absolute archive path and new folder", "Choose an absolute archive path or an absolute new imported folder with an existing parent. Existing files and folders are refused. Choose a new name after a conflict.", Projects;
    PortableExport, "Export portable project", "Checksum-verified .ompack archive", "Export the inspected musical revision with embedded audio, controls, notes, automation, unknown device state and selected originals. Changed revisions require inspection again. Export leaves the current session and its saved baseline intact.", Projects;
    PortableReview, "Review portable archive", "Untrusted metadata preview", "Read the bounded dependency manifest before import. Preview does not prove the payload. Import verifies the complete archive, every entry, embedded PCM, selected source audio and device identities.", Projects;
    PortableImport, "Import portable project", "New private folder; no replacement", "Verify and prepare the native session privately, bind collected originals to the new folder and publish it atomically without replacing an existing path. Unavailable effects bypass; unavailable instruments remain silent unless clips retain rendered audio. Uncollected missing originals remain reported, while embedded audio stays playable.", Projects;
    PortableCancel, "Cancel portable operation", "Preserve current session and existing destinations", "Cancel copying, verification or staging before publication. A package already published remains complete and reports success even if cancellation arrives later. Close waits for the worker result; temporary staging is cleaned up.", Projects;
    DependenciesOpen, "Project dependencies", "Embedded audio and retained device state", "Inspect source availability and unavailable devices. Native projects keep embedded audio, clips, automation and device state. Choose moved sources explicitly and save the project after relinking.", Projects;
    DependenciesInspect, "Check project dependencies", "Captured project revision", "Check every embedded source against its exact decoded audio identity and report unavailable device IDs and saved state. Disk work runs in a cancellable worker. Changed projects refuse stale results.", Projects;
    DependenciesSearch, "Search moved sources", "1–64 absolute folders", "Search selected folders for exact decoded audio, including renamed files. Unsupported/non-audio files are counted separately. Symlinks, nested foreign mounts, damaged audio and read errors produce a partial result; additional matches may exist. Successful decodes charge their actual PCM size; failed decodes retain conservative work credit.", Projects;
    DependenciesChoose, "Review replacement source", "One explicit choice per asset", "Compare candidate paths and choose each replacement. Duplicate matches remain unresolved until you choose. Keep current source reference clears an unapplied choice.", Projects;
    DependenciesApply, "Apply reviewed relinks", "Verified complete batch", "Recheck every chosen file, decoded audio and mount before updating project source aliases as one batch. Failure or cancellation preserves all current references. Save the project to retain completed relinks.", Projects;
    DependenciesCancel, "Cancel dependency operation", "Preserve current source references", "Cancel worker inspection, search or verification before its result is applied. Completed relinks remain in the project.", Projects;
    DependenciesClose, "Close dependency report", "Explicitly retain or discard pending review", "Close the report when idle. Pending choices and operations require explicit discard before close or project replacement. Discard cancels pending work and preserves previously applied source aliases. Choose the project action again after resolving the review.", Projects;
    TimingOpen, "Tempo and meter", "Shared quarter-note timeline", "Open the native timing draft. Tempo ramps rise or fall linearly in BPM to the next point. Meter markers and pickups change bar labels without moving musical events. Apply is one guarded History entry; save the project to retain it.", Editing;
    TimingPoints, "Tempo and meter points", "Ordered beats on the source PPQN grid", "Tempo rows contain beat, BPM and step/ramp. Meter rows contain beat and numerator/denominator. Both lists start at zero and allow up to 4096 points. Tempo is 40–240 BPM; the final tempo point uses step. Meter denominators are powers of two through 128. Invalid rows refuse the complete edit.", Editing;
    TimingClick, "Pickup and click settings", "Quarter-note pickup; meter-beat subdivisions; full count-in bars; linear gains", "A pickup is shorter than the first bar and precedes its first meter change. Subdivisions are 1, 2 or 4. Count-in is 0–4 full bars at the starting meter and tempo, holding clips and recording while decks continue. Accent and beat gains are 0–2; zero silences that click voice.", Recording;
    TimingApply, "Apply timing", "Atomic renderer-confirmed edit", "Prepare and validate the whole map on the worker, then apply it as one History entry. Changed project identities, stale timing, active recording, held notes, count-in and performance protection refuse the edit. Queued is not Applied. Save retains exact ramps; MIDI export samples ramps at each MIDI tick with a 131072-tick bound.", Editing;
    TimingCancel, "Cancel timing operation", "Cancellation before renderer ownership", "Cancel preparation or a queued edit. An already claimed edit reports its actual completed outcome and remains in History. Unapplied drafts survive cancellation and failure.", Editing;
    TimingClose, "Close or discard timing draft", "Explicit unapplied-work decision", "Close, Escape, application exit and project replacement preserve dirty drafts until Keep or Discard. Discard requests cancellation and closes only after pending work settles. Choose the project action again afterward. Completed edits remain in History; reopen the editor to inspect current timing.", Editing;
    HistoryOpen, "Performance history", "Independent saved DJ sessions", "Inspect renderer-confirmed digital main-output contribution. Session history is independent of project Save and Undo. Hardware delivery and human listening require separate verification.", Dj;
    HistoryStart, "Start performance session", "Actual output boundary", "Begin only when the audio output callback acknowledges the request. Already loaded decks are included as unplayed until measurable main-output contribution. Start never starts playback.", Dj;
    HistoryEnd, "End performance session", "Actual output boundary and durable save", "Finish pending measurement windows at the renderer boundary and save the session. Playback continues. A save failure remains pending; ending alone is not proof of persistence.", Dj;
    HistorySelect, "Select performance session", "Stable session identity", "Inspect one saved or active session without changing playback. Interrupted sessions retain their last saved prefix and are marked incomplete.", Dj;
    HistoryMark, "Played status override", "Played / unplayed / measured", "Set a manual assertion on this captured session and entry, or restore automatic status. Measured duration is preserved. Performance protection excludes manual history edits.", Dj;
    HistoryExternal, "External track assertion", "Title and artist; at most 1024 UTF-8 bytes each", "Add a track played outside this engine. It is explicitly external with no measured deck or duration. A nonempty title is required. Performance protection excludes this optional edit.", Dj;
    HistoryExport, "Export performance session", "New JSON, text, CSV or M3U8 file", "JSON, text and CSV retain measured history and manual marks without media paths. M3U8 includes only played entries and requires explicit file-location consent plus the exact recorded local version. Unavailable entries refuse the whole playlist. Existing files are never overwritten. Performance protection excludes exports.", Dj;
    HistoryPublish, "Optional now-playing feed", "Preferences → Automation and remote control", "Off by default. Apply enables a read-only now_playing automation endpoint and chooses title, artist and opaque identity fields. Only recent renderer-confirmed digital output contributes tracks. Muted, paused, disabled, stale and disconnected feeds remove labels. Paths and fingerprints are never published. This does not measure speakers or listening.", Dj;
    HistoryRetry, "Retry history persistence", "Pending essential save or close", "Retry buffered history writes without discarding measurements or changing an already confirmed session end. Recording and automatic saves remain available during performance protection.", Dj;
    HistoryKeep, "Keep working after history close", "Cancel exit", "Cancel exit and reopen history control after any pending boundary completes. An already ended session stays ended; explicitly start another session to record again.", Dj;
    HistoryClose, "Close without confirmed history save", "Explicit loss warning override", "Exit despite incomplete history persistence. Recent measurements and edits may be lost. Previously saved history is retained, and an active saved session will be marked interrupted on restart.", Dj;
    NamedCrates, "Named ordered crates", "Saved collections; All tracks is a virtual view", "Choose a named crate or All tracks. Search crate names separately from tracks, filter saved favorites, or reveal the selected track’s direct manual and automatic memberships. Choosing discovery results retains the original track query, selection and scroll for Return to previous crate view. Nested children are separate views. Use Alt+Up/Down to browse the filtered results and Alt+Home/End for the first/last. Learn Browse crates with an explicit relative encoder and Return with a note button; controller events capture exact crate identities. Browsing remains available during performance protection; pinning and edits require Studio. Closing this manager does not cancel an admitted edit.", Dj;
    PlaylistImport, "Import local playlists", "M3U/M3U8 and Apple XML; 4096 references in 128 playlists", "Open Import playlists from Named crates. Choose an absolute UTF-8 file and optional explicit path-prefix mapping. Review resolved local containers, missing paths, protected/provider-only entries and duplicates. Select playlists and explicitly permit any reported exclusions before importing. Fresh static crates retain first-occurrence order; Apple folders are flattened and smart-playlist rules are not recreated. Existing exact versions retain preparation. Changed media refuses publication and requires another review. Closing the panel does not cancel an admitted operation; Cancel works before the catalog save claim. Source files are never rewritten.", Dj;
    CrateName, "Crate name", "1–256 UTF-8 bytes", "Use a trimmed name without control characters, unique among siblings. Rename changes only the saved collection name. IDs and audio files are preserved.", Dj;
    CrateCreate, "Create root or child crate", "At most 4096 crates and 32 levels", "Create an empty root or a child of the selected crate. The catalog owner generates a stable identity; Queued is not Saved. Wait for the durable result before another edit.", Dj;
    CrateDelete, "Delete crate subtree", "Explicit membership-only confirmation", "Review the exact named subtree and membership count, then confirm or keep it. This deletes collections and membership references only, never catalog tracks, source audio, sampler references or project PCM.", Dj;
    CrateOrder, "Manual crate and member order", "Stable identity anchors", "Move sibling crates up or down, move a child out, or reorder selected members before an unfiltered row. Last row plus one appends. Selected members retain their relative order as one group; selecting their own anchor is rejected. Filtering never sorts a named crate.", Dj;
    CrateDestination, "Copy, move and nesting destination", "An explicitly selected saved crate", "Choose a crate and Use as destination, then select a source. Copy keeps memberships in both crates; Move removes them from the source and inserts them in the destination. Nest moves a collection under the destination; cycles are rejected. No action moves an audio file.", Dj;
    CrateAdd, "Add captured library tracks", "At most 4096 tracks per edit", "Add the selected track or filtered view to the chosen destination crate, appending in visible order. Existing members are retained without duplicates or reordering. Capture uses stable catalog TrackIds. Unsaved rows and oversized batches are refused without partial changes.", Dj;
    CrateMembership, "Select or remove direct memberships", "At most 4096 selected TrackIds", "Checkboxes select exact track identities for a later operation. Remove changes only the current crate, leaving the track in other crates and the library. Child memberships are separate.", Dj;
    CrateCancelEdit, "Cancel or retry a crate edit", "Actual catalog outcome", "Cancel requests cancellation before publication. If publication already won, wait for the truthful result. Retry is available only for a rejected edit and keeps its captured identities. Committed or unknown outcomes must not be repeated blindly.", Dj;
    SupportOpen, "Support and crash reports", "Local redacted evidence", "Inspect bounded structured events, numeric routing and performance counters. No uploader or audio plugin host exists. Original media, paths, titles, device names, raw errors, credentials and panic payloads are excluded.", Emergency;
    SupportInspect, "Inspect current support report", "Snapshot of bounded collected evidence", "Build a reviewable JSON preview on a worker. Collection may lag the engine; confirmed persistence time is separate from current observations.", Emergency;
    SupportCategories, "Support report categories", "Explicit included fields", "Choose routing, structured events, performance counters and opaque recovery references. Changing inclusion invalidates the old preview and requires another review before export.", Emergency;
    SupportPrevious, "Find previous support runs", "Private retained reports", "Read inactive run markers and their last bounded report. An observed Rust panic differs from an unclean exit; a kill or power loss does not identify its cause. Active or unreadable records are reported explicitly.", Emergency;
    SupportPath, "Support report file", "Local JSON destination or source", "Choose a local .omasupport.json path. Export creates a new private file and refuses existing destinations. Reopen validates bounds and schema without applying project data.", Emergency;
    SupportReopen, "Reopen support report", "Validated local JSON", "Inspect an existing redacted report. Malformed, unsupported, oversized, symlink and non-regular inputs are rejected; the current project is unchanged.", Emergency;
    SupportConsent, "Review before local export", "User decision", "Confirm that you reviewed this exact preview before creating a local report. There is no network upload; sharing a file remains a separate explicit user action.", Emergency;
    SupportExport, "Export reviewed support report", "Local create-new publication", "Write exactly the reviewed report on a cancellable worker. A completed publication is reported truthfully even after late cancellation; durability warnings stay visible.", Emergency;
    SupportCancel, "Cancel support work", "Pending optional work", "Cancel inspection or export before publication. A committed local file remains exported. Live audio and the current project are unchanged.", Emergency;
    SupportRecovery, "Find exact linked recovery", "Opaque session digest and durable sequence", "Verify the exact retained journal record without substituting a newer one. Preview it in Recovery, then use the normal Save/Discard/Cancel restoration workflow. A pruned or corrupt record remains explicitly unavailable.", Projects;
    SupportRestart, "Restart normally", "Explicit exit from safe mode", "Safe mode opens no audio or MIDI devices and leaves startup settings unapplied. Save, discard or cancel unsaved work before restarting. Only a completed close starts normal device setup; playback does not resume automatically.", Emergency;

    AnalysisClose, "Close analysis panel", "Hide the window only", "Close the inspector while an admitted queue continues. Use Cancel analysis queue to stop remaining work; hiding the window never relabels a committed result.", Dj;
    TagEditor, "Read and edit audio metadata", "Embedded tags and durable library sidecars", "Inspect a selected track or capture a filtered batch. Actual embedded title, artist, BPM and key carry tag provenance; missing fields explicitly use filename fallbacks. User sidecars take precedence. Loaded audio and manual beat grids keep their current performance values.", Dj;
    TagInspect, "Inspect captured audio tags", "1–4096 saved current local tracks", "Read actual tag values and notices off the GUI. Batch review captures exact sources and versions; later browsing, filtering or selection cannot retarget them. Imperfect, unsupported or read-only media remain available for sidecar editing.", Dj;
    TagField, "Choose changed metadata fields", "At most 4096 UTF-8 bytes per field", "Check only fields to change. Unchecked keeps each track's value; checked and empty clears it. BPM must be empty or a finite number greater than 1. Review the exact changed values before applying them to the captured tracks.", Dj;
    TagStorage, "Embedded tags or sidecar values", "MP3, FLAC, WAV and AIFF embedded writes up to 128 MiB", "Enable supported embedded rewrites after complete audio and unrelated-metadata preservation checks. Larger, read-only, hard-linked, protected or unsupported metadata uses a durable library sidecar. Fractional BPM unsupported by an integer tag stays precise in the sidecar; no value is silently rounded.", Dj;
    TagReview, "Review metadata changes", "Captured fields and media identities", "Freeze the selected field changes before applying them. Editing a field or changing storage mode invalidates that review. Inspect the captured source paths and actual embedded values, especially before a batch clear or replacement.", Dj;
    TagApply, "Apply reviewed metadata edits", "One durable track transaction at a time", "Recheck each captured file and catalog identity. Stage supported rewrites privately, prove unchanged audio and retained unrelated metadata, then journal and atomically replace the file. Retain the original until the library confirms its save. A batch may finish partly; earlier saved tracks remain saved after cancellation.", Dj;
    TagCancel, "Cancel metadata work", "Truthful partial-batch outcome", "Cancel inspection or remaining edits before their file claim. A file already replaced still completes its essential library save, even after Performance protection or close. Failed or unconfirmed writes retain recovery records and originals.", Dj;
    TagRecovery, "Retry metadata recovery", "Durable tag journals and original backups", "Retry catalog persistence and inspect pending tag journals on the filesystem owner. Complete verified installed edits or retire verified uninstalled staging. Conflicting external edits are preserved and reported; recovery never blindly overwrites another file.", Emergency;
    LibraryAnalysis, "Background track analysis", "Local source/version cache", "Open the bounded background analysis queue. Opening this panel neither decodes nor changes playback. Musical-key estimates are stored separately from filename hints and saved tags. Review conventional and harmonic notation, unknown results and profile correlation before correcting a key through Audio metadata.", Dj;
    AnalysisFields, "Analysis fields", "BPM / duration / waveform / source level / musical key", "Choose which measured fields to prepare. Each result stays qualified by source identity, file fingerprint, digest and algorithm version. Manual BPM and locked preparation retain precedence. Waveforms store bounded low/mid/high band mean magnitudes, not playable PCM. Source level stores whole-track RMS, sample peak and a bounded gain recommendation; analysis does not apply gain. Musical key uses the first stereo pair or mono channel and keeps weak or ambiguous estimates unknown. Analysis never overwrites saved key edits.", Dj;
    AnalysisForce, "Force selected fields", "Reanalysis of chosen fields only", "Recompute the chosen fields even if verified cache entries exist. Unselected analysis fields and manual preparation remain unchanged. A missing or corrupt waveform is recomputed without trusting that cached blob. Force never overrides BPM or metadata locks.", Dj;
    AnalysisSelected, "Analyze selected row", "One captured local source", "Capture the selected row's identity and prepare missing chosen fields on the shared media worker. A deck or sampler load preempts background decoding. Ready means prepared, not persisted; wait for the catalog receipt.", Dj;
    AnalysisCrate, "Analyze filtered crate", "1–4096 captured rows", "Capture the current filtered view without cloning the crate. Process one source at a time and wait for each actual save result before advancing. Later sorting, filtering, scanning or selection does not retarget the queue. Narrow larger crates; no silent truncation.", Dj;
    AnalysisInspect, "Inspect selected cache", "Verified cached record and waveform", "Use Preview selected/filtered analysis changes to inspect the fields that will refresh and the current values protected by locks, without decoding or saving. Read the selected source/version's saved record and verify the waveform on the metadata worker. Missing fields are reported; inspection alone never starts source decoding. A changed source cannot inherit another version's result.", Dj;
    AnalysisRetry, "Retry current analysis", "Explicit resume after failure or preemption", "Retry the captured current source after a foreground load, protection or storage failure. This preserves earlier commits and never silently substitutes the currently selected row. Optional work is refused while performance protection is active.", Dj;
    AnalysisSkip, "Skip current analysis", "Advance the captured queue", "Leave this source's saved values unchanged and proceed to the next captured row. Earlier results remain saved; source files are never edited by analysis.", Dj;
    AnalysisCancel, "Cancel analysis queue", "Cooperative cancellation", "Stop remaining work and request cancellation at safe decode, hash and publication boundaries. An OS read may still finish. A save whose publication claim already won reports its actual committed result instead of being relabeled cancelled.", Dj;
    Help, "Help and lessons", "Offline reference", "Open task guidance, focused-control context, active shortcuts and observed-state lessons. Opening help never changes audio.", Setup;
    HelpTopic, "Choose help workflow", "Reference only", "Read a task chapter without changing your active lesson or musical state. Start this lesson deliberately captures a fresh baseline.", Setup;
    HelpSearch, "Search control reference", "Text filter", "Find implemented control descriptions by name, units or purpose. Filtering help does not filter the crate.", Setup;
    HelpReference, "Control reference entry", "Expandable offline description", "Read this control's purpose and units. The entry does not perform the named musical action.", Setup;
    HelpShortcuts, "Active shortcut reference", "Current profile bindings", "Expand the effective shortcut table and keyboard/assistive input instructions. Customize bindings in Preferences; this reference alone does not change them.", Setup;
    LessonStart, "Start guided lesson", "Observes current document", "Start or restart this task guide. Lessons never reset your document, start audio, bypass unsaved-work prompts or submit musical edits for you.", Setup;
    LessonNext, "Next lesson step", "Observed completion required", "Advance only after the current step has published evidence. Queue acceptance is insufficient. For physical checks the separate checkbox records only your self-reported observation.", Setup;
    LessonCancel, "Cancel lesson", "Guide only", "Stop this guide without undoing your work, stopping audio or releasing a held gate. Use the actual session/deck controls to stop playback.", Setup;
    LessonPhysical, "Physical observation", "Self-reported; not software proof", "Confirm only what you personally heard or tested on hardware. This does not certify compatibility, routing or lack of dropouts.", Setup;
    Preferences, "Preferences and profiles", "Saved versus running configuration", "Edit a profile, preview resolved changes, then Apply and save. Draft changes do not affect playback. Saving audio choices does not switch the running stream. Use the separate Audio devices confirmation or restart; live MIDI policy has its own requested/applied result.", Setup;
    PreferenceProfile, "Profile to edit", "Studio / performance / named copies", "Select which saved profile to edit. Selecting the editor profile alone does not activate it.", Setup;
    PreferenceActivate, "Activate profile", "Selected preference profile", "Choose the profile intended for activation on Apply and save. Audio differences remain saved intent until explicit device confirmation or restart; MIDI and appearance report actual application separately.", Setup;
    PreferenceClone, "Clone profile", "Independent named copy", "Create an editable copy in the draft. Nothing is persisted until Apply and save.", Setup;
    PreferenceRename, "Profile name", "Nonempty unique text", "Rename the draft profile. Validation reports conflicts before saving.", Setup;
    PreferenceAudioDevice, "Output device", "System default or exact device name", "Save the exact output device name, or follow the system default. Preview resolves availability and rejects ambiguous names. Apply saves the choice; a separate Audio devices confirmation or restart changes the stream.", Setup;
    PreferenceAudioRate, "Requested sample rate", "8000–384000 Hz; advertised options or device default", "Save an advertised output rate. The common 44.1/48/96/192 kHz choices appear only when advertised. Preview validates the whole configuration; saved intent and backend-accepted logical settings are distinct from physical negotiation.", Setup;
    PreferenceAudioBuffer, "Requested buffer frames", "16–32768 frames; optional device default", "Save an advertised output buffer request, or let the backend choose. Apply saves it without switching audio. Requested buffer duration, observed callback size and backend scheduling estimates differ; smaller requests do not prove fewer dropouts.", Setup;
    AudioDevices, "Audio devices and latency", "Saved intent / active stream / observed timing", "Inspect the active output and preview saved choices. Opening this window neither changes devices nor emits a probe. Save edits in Preferences before previewing them here.", Setup;
    AudioBackend, "Audio backend", "System backend or advertised backend name", "Save the backend used to resolve input and output device names. An unavailable saved backend fails visibly rather than silently choosing another route.", Setup;
    AudioOutputFormat, "Output sample format", "Advertised integer or floating-point PCM", "Save a format supported by the selected output layout and rate. Device default lets the backend select; unsupported combinations fail preview instead of silently falling back.", Setup;
    AudioInputDevice, "Calibration input device", "System default or exact input name", "Save the input used only for explicit loopback calibration. This does not enable input monitoring or general external-audio recording. Calibration uses the currently active output's logical rate.", Setup;
    AudioInputChannels, "Calibration input channels", "1–64 advertised interleaved channels", "Save the temporary input stream's channel count. Select the actual capture channel separately; all channel numbers are interleaved positions, not verified connector labels.", Setup;
    AudioInputFormat, "Calibration input sample format", "Advertised integer or floating-point PCM", "Save the temporary input format. Preview checks it against the active output rate and chosen input layout before any probe can run.", Setup;
    AudioInputBuffer, "Calibration input buffer", "16–32768 advertised frames or device default", "Save the temporary input buffer request. Together with an explicit output buffer this permits a buffer-only estimate; driver and converter time are excluded.", Setup;
    AudioInputChannel, "Calibration capture channel", "One-based channel 1–64", "Choose which input channel captures the loopback probe. Preview rejects a channel outside the selected input stream. No captured input is monitored to output.", Setup;
    AudioOutputChannel, "Loopback probe output channel", "One-based channel 1–64", "Choose which active output channel emits the probe. Other probe-stream channels are silent. Preview rejects channels outside the active output stream; verify the physical route yourself.", Setup;
    AudioProbeLevel, "Loopback probe level", "−60 to −24 dBFS", "Set the digital level of three short coded probes. This does not control external amplifier volume. Use a suitable line-level route, disable monitoring and turn down speakers before explicit confirmation.", Setup;
    AudioPreview, "Preview saved audio", "Read-only device discovery", "Resolve the saved profile against current input/output capabilities and the active calibration route. Preview changes no stream and plays no probe. Save draft preference edits first.", Setup;
    AudioUse, "Use saved audio now", "Opens disruptive-change confirmation", "Review the proposed output before choosing Stop and change output. This first button alone does not stop playback or activate the device.", Setup;
    AudioReconnect, "Reconnect retained output", "Explicit retained-output recovery", "After device loss, reconnect only the retained physical identity or graph-server namespace and exact routes. JACK and PipeWire use the retained server clock after confirmation; ALSA keeps its accepted configuration. Unverified default aliases need explicit preview and fallback confirmation. Playback remains stopped, emergency mute remains latched and physical inputs need acknowledgment before Play. Native transport starts ramp output over 2 ms.", Setup;
    AudioConfirm, "Stop and change output", "Explicit disruptive operation", "Stop decks, clips, recording and held notes, then activate the previewed output. Failure attempts the previous output; double failure retains the session for Save, New/Open and Close. Playback remains stopped even after success or rollback.", Setup;
    AudioKeep, "Keep current audio", "Dismiss confirmation", "Dismiss the device-change or probe confirmation without submitting it. Saved preferences remain saved; the current output is unchanged.", Setup;
    AudioMeasure, "Measure loopback", "Opens physical-route confirmation", "Review the chosen input, active output, channel numbers and probe level. This button alone emits no sound. A suitable physical cable or interface loopback is required.", Setup;
    AudioProbeConfirm, "Cable ready: stop and measure", "Explicit line-level loopback probe", "Confirm your chosen route, disable input monitoring and turn down external speakers. Stop performance, emit three low-level probes, capture up to three seconds, then restore output without resuming. Missing, noisy, clipped, ambiguous or inconsistent evidence produces no measurement.", Setup;
    AudioCancel, "Cancel audio operation", "Cooperative cancellation", "Request cancellation at safe worker boundaries; operating-system calls may still finish. Cancellation before output activation restores the prior route; a change already committed is reported honestly. Cancelled calibration produces no current measurement.", Setup;
    AudioNotice, "Audio operation status", "Pending / applied / rollback / offline", "Read the operation's actual result. Dismiss hides only the notice. An offline retained session still supports Save, New/Open and Close; queue acceptance is not proof that an output is running.", Setup;
    AudioCapabilities, "Advertised device capabilities", "Backend ranges; not physical qualification", "Expand input/output device ranges for formats, channels, rates and buffers. Exact names are not portable serial identities; duplicates are rejected. Discovery errors and truncation are explicit, and unknown buffer limits are not invented.", Setup;
    AudioActive, "Backend-accepted output", "Logical device configuration", "Read the configuration accepted by the backend. CPAL does not report the physical negotiated sample rate or converter latency; these logical settings are not a physical hardware measurement.", Setup;
    AudioTiming, "Observed callback timing", "Frames / milliseconds", "Read completed callbacks for the current stream. Callback duration uses its logical sample rate; backend output scheduling estimates are separate from driver/converter roundtrip and measured dropouts.", Setup;
    AudioBufferEstimate, "Roundtrip buffer estimate", "Requested input plus output frames / logical rate", "Estimate only the sum of explicitly requested buffers. Driver and converter time are excluded. If either buffer is backend-selected this estimate is unavailable.", Setup;
    AudioMeasurement, "Measured loopback return", "Host callback-to-callback timing / resolution / repeat spread", "Read a result matched to the exact current profile and preview. Three reliable recorded probes establish host callback-to-callback return timing, not converter-only physical roundtrip. Old, cancelled or unrelated measurements are not shown as current.", Setup;
    PreferenceNotice, "Dismiss preferences notice", "Message only", "Hide this notice without retrying, saving or changing the running profile.", Setup;
    PreferenceDelete, "Delete profile", "Inactive draft profile", "Remove this inactive profile from the draft. The active profile cannot be deleted; Apply and save commits the draft.", Setup;
    PreferenceReset, "Reset profile to defaults", "Selected draft profile", "Replace this profile's draft values with defaults. Cancel discards the draft; Apply and save commits it.", Setup;
    PreferenceReload, "Reload saved preferences", "Local saved file", "Read the saved preferences back into the editor. Unsaved draft changes may be replaced; validate and apply deliberately.", Setup;
    PreferenceRecover, "Preserve old file and reset preferences", "Explicit recovery", "Keep the unreadable/changed file as a backup, then create default preferences through the recovery worker. Failure remains visible rather than destroying the only copy.", Setup;
    PreferenceAudioChannels, "Requested output channels", "1–64 advertised channels or device default", "Save an advertised output stream channel count. Main uses channels 1/2, mono sums them and additional channels are silent; this does not create extra mixer or headphone buses.", Setup;
    PreferenceMidiRetry, "Retry saved MIDI policy", "Saved policy to live connection worker", "Request the saved profile’s policy again. Inspect applied generation and missing/failed ports; retry admission is not connection success.", Controllers;
    PreferenceMidiPolicy, "MIDI input policy", "All / selected exact names / disabled", "After Apply and save, request the live connection policy. Check requested/applied generation, missing ports and errors; saving alone is not connection success.", Controllers;
    PreferenceMidiNames, "Selected MIDI input names", "One exact port name per line", "Enter explicitly allowed inputs for Selected policy. Missing names remain missing; they never fall back to enabling all ports.", Controllers;
    MidiRouteEnable, "Explicit track MIDI routing", "Saved studio/performance profile", "In Preferences, choose exact input/output ports and track mappings. Preview and Cancel preserve live routing; Apply and save requests the saved routing. Inspect the applied generation and errors in MIDI. The input policy must also permit each input. Leaving explicit routing off keeps established controller maps and selected-track keyboard notes.", Controllers;
    MidiRouteTrack, "MIDI destination track", "One route per stable track slot1–128", "Assign each physical port/channel to a fixed track independently of browsing. Several inputs may feed a track and the same input may feed several tracks. Held notes release their original destination. Track routing belongs to the active profile.", Controllers;
    MidiRoutePort, "MIDI route device and port", "Exact case-sensitive name and optional backend id", "Choose a discovered port or enter its exact name. Use a backend id to disambiguate identical names. Missing or ambiguous outputs are refused. Configured or active input devices/clients cannot also be an output destination. Select controller inputs explicitly and deselect the output device in Input policy. No first-port fallback is used.", Controllers;
    MidiRouteChannel, "MIDI route channels", "Input channel mask; output1–16 or Preserve", "Choose accepted input channels1–16 and optionally rewrite outgoing channel messages. Preserve retains each source channel; complete SysEx has no channel and is not rewritten.", Controllers;
    MidiRouteMonitor, "Monitor routed MIDI notes", "Internal instrument monitoring", "Play accepted notes on this route's fixed internal track. Bank/program, controllers, pressure, bend and SysEx are external MIDI messages; internal monitor does not interpret them as synth controls.", Controllers;
    MidiRouteThru, "Live MIDI thru", "Explicit external output only", "Send accepted live messages to the route's external port. Controller mappings remain separate. Configured and active input/output device overlap is refused, including controller-map inputs. Review physical MIDI cable/thru connections separately; packet equality cannot distinguish a returned echo from a legitimate repeated note.", Controllers;
    MidiRouteFilter, "MIDI route message filters", "Notes, CC, bank, program, pressure, bend, SysEx", "Filter each type independently. CC0/32 use Bank rather than ordinary CC. Pressure includes polyphonic and channel pressure. SysEx is off by default and accepts complete7-bit-data F0…F7 packets of at most256 bytes; fragmented or larger packets are refused. External clip output plays source notes and channel lanes before the internal arpeggiator/audio mix. Output has2048 queue slots and at most256 renderer messages per audio block; overload resets outputs and refuses that clip until a new launch, clip edit or routing change. Concurrent owners at one port/channel/pitch share one physical gate, retaining the first onset velocity until every owner releases. Sustain combines active owners; disconnect/clip stop releases only its owner. Other channel controls use received order when tracks share an output channel. Past controllers are not chased after a seek/route change.", Controllers;
    MidiRouteCancel, "Cancel pending MIDI routing", "Before publication claim", "Cancel keeps the previous applied routing when it wins before the worker's commit claim. A backend open/send already in progress must return before its receipt. A change that won the claim reports Applied; closing the panel does not undo a committed route.", Controllers;
    MidiRouteReset, "All notes off / reset MIDI outputs", "Explicit output-owner reset", "Request all-sound-off, all-notes-off, reset controllers, centered bend and zero channel pressure on every connected output channel. Queue overflow and route/device changes also invalidate older outgoing events and request reset. Reset also stops the currently running external clip streams until relaunch, clip edit or routing apply; internal audio transport remains running. Backend errors report unconfirmed reset; this is not proof of physical hardware silence.", Emergency;
    PreferenceLibraryRoots, "Library locations", "One local path per line", "Choose locations for background scan. A changed active profile cancels/restarts discovery while keeping the visible crate until complete results arrive.", Dj;
    PreferenceScale, "UI scale", "50–300%", "Scale the interface after a successful Apply. Draft values alone do not change the live window.", Setup;
    PreferenceFont, "Font size", "8–48 points; optional desktop/default size", "Override the text size after Apply or keep the selected theme's size. Font selection remains the desktop font policy.", Setup;
    PreferenceTheme, "Follow desktop theme and font", "On / off", "Use validated live desktop theme/font updates when enabled. Disabling selects the app's default appearance; invalid updates retain last good settings.", Setup;
    PreferenceStartup, "Startup options", "Scan / help / MIDI windows", "Choose which background scan and panels start next time. Saving this option does not close the current project.", Setup;
    PreferenceShortcut, "Shortcut override", "Exact key and modifiers / disabled", "Override a stable named action in the active profile. Preview/Apply validate conflicts and reserved editing chords. In-app help shows effective bindings.", Setup;
    PreferencePreview, "Preview changes", "Read-only background resolution", "Resolve devices/routes and validate the draft without saving or changing the running engine. Missing hardware and unsupported routes remain explicit.", Setup;
    PreferenceApply, "Apply and save preferences", "Validated atomic local file", "Persist the validated draft before applying appearance/library/MIDI changes. Audio choices remain saved intent until the separate Audio devices confirmation or restart. Failure keeps running preferences unchanged. Configure panel layout copies named workspaces, reorders/hides/resizes panels and opens secondary windows. Use current window sizes before Preview and Apply. Cancel retains the applied layout; closing a panel window returns it to the main window for this session.", Setup;
    PreferenceCancel, "Cancel preference changes", "Draft / pending operation", "Cancel pending work before commit or discard the draft and close the editor. A save already committed is reported as committed.", Setup;
    PreferenceImport, "Import preferences", "Validated Omatainer preference JSON", "Read a preference file into the draft on a worker. It does not activate or overwrite running preferences until Apply and save.", Setup;
    PreferenceExport, "Export preferences", "Local preference JSON", "Export validated draft preferences to the chosen local file. Existing-destination policy is explicit; exporting does not activate a profile.", Setup;
    PreferenceFilePath, "Preference import/export path", "Local filesystem path", "Choose a source/destination for portable preferences. No network transfer occurs.", Setup;
    RecoveryOpen, "Autosave and recovery", "Independent recovery copies", "Open the recovery status and inactive-session list. Batched full edit-state records normally capture dirty work about every two seconds, including untitled projects. Confirmed durable age is the actual loss-window evidence; explicit project files are never overwritten.", Projects;
    RecoveryStatus, "Last confirmed durable recovery", "Seconds and revision", "Captured-state age advances only after that state has a confirmed durable journal commit. The separately labeled commit acknowledgment may be newer after slow I/O; edits accepted during the write are not included automatically. Busy capture, full storage and I/O failure keep the prior confirmed state. Newer edits may be lost until the next confirmed record; a committed durability warning is not a durable acknowledgment.", Projects;
    RecoveryRefresh, "Refresh recovery list", "Inactive sessions", "Discover bounded, validated inactive recovery candidates on the worker, including sidecar hashing. Performance protection defers this work and invalidates old verified lists; leave protection and Refresh for a fresh selection. Active sessions remain locked. A malformed tail stops replay at its valid prefix and is reported; incomplete or corrupt media is never silently omitted.", Projects;
    RecoveryNow, "Journal current edits now", "Background capture", "Request the next coherent edit-state record without changing playback. This is an asynchronous request, not confirmation of durability. Read the resulting durable timestamp and warnings.", Projects;
    RecoveryPreview, "Preview recovery", "Read-only validation", "Validate the selected record and embedded media on the worker and display its notes, media and recovery report. Preview does not replace the current project or write its explicit saved path. Performance protection rejects or cancels this optional PCM verification; a cheap protected-startup availability notice and automatic durability remain available. Full discovery is deferred until you leave protection and Refresh.", Projects;
    RecoveryRestore, "Restore as untitled copy", "Stopped, unsaved document", "Use the ordinary Save / Discard / Cancel protection before installing the selected recovery. The recovered project starts stopped as a dirty untitled copy; Save As chooses a new explicit file. The original path is informational and is not overwritten.", Projects;
    RecoveryDelete, "Delete recovery session", "Every generation in one session", "After explicit confirmation, permanently discard this inactive session's journal, checkpoints and sidecars. A session lock and candidate identity prevent deleting active or changed recovery. Explicit project files are unaffected. Performance protection excludes this optional explicit deletion; automatic committed-checkpoint cleanup remains essential durability.", Projects;
    RecoveryCancel, "Cancel recovery operation", "Before commit", "Cancel pending preview, discovery or deletion without changing the current project. A deletion or durable write that already committed remains truthful; cancellation cannot undo a committed filesystem operation.", Projects;
    RecoveryRetry, "Retry recovery retirement", "Intentional close", "Retry recording that this document epoch was intentionally closed. Failure leaves a visible warning and may offer the recovery copy again after restart; it never changes the explicit project Save decision.", Projects;
    RecoveryKeepWorking, "Keep working after recovery close", "Cancel exit", "Cancel the exit and release its existing project close guard. Recovery restarts in a fresh session, including when the retirement marker already committed. Playback does not resume automatically.", Projects;
    RecoveryClose, "Close and retain possible recovery", "Explicit warning override", "Finish the authorized exit even when recovery retirement failed or its durability is uncertain. The remaining copy may be offered at startup. This does not label unsaved work as explicitly saved.", Projects;
    RecoverySettings, "Autosave and recovery limits", "Saved profile settings", "Configure checkpoint compaction, retained generations per session and the global storage cap. Dirty edit-state journal batches remain separate from checkpoints. Apply and save persists these settings; it is not a journal durability acknowledgment.", Projects;
    RecoveryInterval, "Recovery checkpoint interval", "5–3600 seconds", "Choose how often the edit-state journal compacts into a checkpoint. Dirty state is batched about every two seconds independently; capture, queue pressure and disk I/O can increase the loss window. Read the observed last durable age in Recovery.", Projects;
    RecoveryRetention, "Recovery generations per session", "2–20 generations", "Retain checkpoint generations within each session, preserving a known-valid prior generation until a newer durable commit. This does not silently delete another session's recovery history.", Projects;
    RecoveryStorage, "Recovery storage limit", "64–16384 MiB globally", "Bound embedded media, journal, checkpoint and staging storage together. Full storage stops new durable writes and reports the failure. The only usable recovery is never removed automatically to make room; explicit project files are outside this store.", Projects;
    ClosePanel, "Close panel", "View only", "Hide this panel without changing the audio or deleting its data.", Setup;
    Actions, "Control actions", "Focused control", "Open the focused control's alternate actions. Shift+F10 provides the same choices; controls without alternatives disable the menu.", Setup;
    NumericEditor, "Direct numeric entry", "Control's displayed units and bounds", "F2 opens a focused value editor. Apply accepts a finite in-range value; Cancel preserves the previous value. Arrows adjust and Shift makes fine adjustments.", Editing;
    Scroll, "Scrollable surface", "Pixels", "Scroll to controls outside the viewport. Focused controls reveal themselves; arrows and Page/Home/End work on the focused scroll view.", Setup;
    DeckLoadLock, "Lock a live deck", "Per-deck session lock", "Lock playing, touched or audibly fading decks independently of performance mode. Mouse, keyboard, dropped-file, controller and IPC replacement/eject requests use the same guard. A quiet stopped deck remains available. Locks survive project and output changes within this app session; restarting starts unlocked. Performance mode protects live decks even when their explicit lock is off.", Dj;
    DeckLoadReview, "Review a deck replacement", "The reviewed deck and track", "Loading or ejecting an active locked deck opens a review of its current track and captured replacement. Acknowledge the replacement before confirming. Preparation leaves old audio loaded until the renderer applies a ready replacement. Failed or cancelled work and changed source, lock or safety generations refuse application. A reviewed eject reports queued separately from renderer-completed. MIDI and IPC cannot confirm this decision.", Dj;
    DeckLoadCancel, "Keep current deck audio", "Cancel an unconfirmed review", "Close this review without submitting a replacement or eject, cancelling an existing decoder or changing current playback. An already confirmed load has its normal pending/loaded/refused receipt; changing safety or the source invalidates its reviewed approval.", Dj;
    PerformanceMode, "Performance protection", "Session safety state", "Protect playing/touched/audibly fading deck loads, destructive edits and project/device changes centrally. Mixing, composing, recording, quiet stopped-deck loads and Save remain available. Leaving requires a deliberate decision; opening a project never disables protection. Explicit deck locks remain independent; a reviewed source-bound override can replace only its confirmed deck.", Emergency;
    PerformanceStop, "Safe stop", "Session and both decks", "Confirm stopping transports, finalizing held captures and releasing input notes. Natural sample/effect tails continue. Input recovery is explicitly acknowledged; transport never resumes automatically.", Emergency;
    PerformanceSilence, "Emergency silence", "All output", "Confirm all-notes-off and a 2 ms output fade to latched mute. Quiet observation alone never unmutes delayed or bypassed history. Explicit stopped DSP reset is required to unmute.", Emergency;
    PerformanceRecovery, "Controlled recovery", "User-confirmed physical release", "Release physical controls and explicitly acknowledge. The renderer drains old queued onsets before reopening controls. This is a user report, not hardware qualification. Emergency output mute stays latched until deliberate DSP reset.", Emergency;
    PerformanceReset, "Reset stopped DSP and unmute", "Audio-owner worker", "Deliberately reclaim the stopped graph, erase voice/effect/filter histories off the callback and reopen the same output. Playback remains stopped. Failed recovery retains emergency mute and reports its status.", Emergency;
    PerformanceCancel, "Keep safety state", "Cancel pending decision", "Close this confirmation without changing protection, transport, input recovery or output mute.", Emergency;
    AdmissionDismiss, "Dismiss admission error", "Message only", "Hide this rejection message. The rejected action was not applied; dismissal does not retry it.", Emergency;
    PitchLock, "Pitch lock", "On / off; 0.50–1.50× forward rate", "On preserves pitch while changing tempo within the supported range. L! means the actual rate is outside that range and tempo and pitch change together. L~ means platter touch temporarily uses direct scratch playback. On release, a playing deck resumes pitch lock if its rate is supported; a stopped deck stays stopped. Original-rate playback passes through directly. Stopped or empty decks show armed status. This is independent of deck tempo sync; Match or Sync can exceed the supported range. Listen before a performance: quality varies with material and rate.", Dj;
    Pitch, "Deck pitch", "Percent; selected ±8, ±16 or ±50 range", "Adjust playback rate around zero. Pitch lock determines whether the file's pitch follows the rate. Center resets to the original rate.", Dj;
    PitchRange, "Pitch range", "±8%, ±16%, ±50%", "Cycle the pitch fader's range. Check the current value after changing range.", Dj;
    GridEditor, "Manual beatgrid editor", "Loaded track; source-time coordinates", "Open a draft grid for this exact loaded track. Analysis BPM may seed an explicitly unverified preview; it never establishes a downbeat. Changing the loaded track closes the draft.", Dj;
    GridOrigin, "Grid downbeat position", "Finite source seconds; negative positions allowed", "Enter the source-time position of beat zero. Earlier source positions have negative beat coordinates. Editing changes the preview only; absolute cues and audio stay unchanged until the separate grid Apply, which still does not move cues.", Dj;
    GridSet, "Set grid downbeat at playhead", "Published source playhead seconds", "Place beat zero at the displayed renderer playhead, using the draft tempo. Enter a valid tempo first when no usable BPM hint exists. This edits only the preview.", Dj;
    GridSlip, "Slip beatgrid", "−10 / −1 / +1 / +10 milliseconds", "Move all draft beat lines by the chosen source-time offset without changing tempo. Preview the alignment before Apply.", Dj;
    GridStretch, "Stretch grid tempo", "20–400 BPM", "Scale every tempo segment around the draft downbeat. All segments must stay between 20 and 400 BPM. Anchors retain beat coordinates; original audio and absolute cues stay unchanged. Bars remain four beats.", Dj;
    GridHalf, "Half grid tempo", "Draft BPM divided by two; minimum 20", "Correct double-tempo ambiguity in the preview while retaining the downbeat. Disabled when the result would fall below the supported range.", Dj;
    GridDouble, "Double grid tempo", "Draft BPM multiplied by two; maximum 400", "Correct half-tempo ambiguity in the preview while retaining the downbeat. Disabled when the result would exceed the supported range.", Dj;
    GridAnchor, "Manual tempo anchors", "Up to 64 ordered anchors; 20–400 BPM per segment", "Map a beat after beat 0 to a position inside the loaded source audio. Insert in any order; an existing beat is replaced. Source and beat positions must increase together. The map stays continuous across boundaries and continues its final tempo after the last anchor. Delete reconnects neighboring segments. Apply commits one undoable grid edit for the same track; Cancel keeps the applied map.", Dj;
    GridReset, "Reset manual beatgrid", "Preview removal", "Preview removing the manual grid. Apply commits removal; Cancel keeps the current grid. Reset does not change analyzed BPM, audio or absolute cue positions.", Dj;
    GridPreview, "Beatgrid preview", "Solid applied / dashed draft; uniform four-beat bars", "Inspect bounded source-time beat markers around the live playhead over a summed low/mid/high magnitude envelope, not raw sample peaks. Beat zero is the first downbeat; negative beat coordinates represent pickups. Colored cue markers keep their source positions. Preview does not alter playback.", Dj;
    GridApply, "Apply manual beatgrid", "One receipt-qualified undoable edit", "Submit the validated draft for the same loaded track. Queued means waiting for renderer preparation; actual application and library durability are reported separately. Manual preparation survives reanalysis without replacing analysis metadata. An accepted edit cannot be cancelled by closing this window.", Dj;
    GridCancel, "Cancel or close beatgrid editor", "Draft only; Escape", "Discard unapplied preview changes and close the editor without submitting an audio or grid edit. Closing after Apply does not cancel a command already accepted by the renderer queue.", Dj;
    CueEditor, "Cue names and colors", "Eight applied hot cues", "Open the loaded track's cue list. Rows show renderer-applied positions, names and colors; fields are drafts until Apply. Changing the track closes the editor.", Dj;
    CueName, "Cue name", "Up to 64 UTF-8 bytes", "Draft a name for an existing hot cue. Apply submits the edit to the same loaded track. Empty names display the cue number; control characters are rejected.", Dj;
    CueColor, "Cue color", "Opaque #RRGGBB or theme", "Draft six hexadecimal color digits. An empty field uses the current theme's cue color. Apply updates pad, waveform marker and cue list together.", Dj;
    CueApply, "Apply cue name and color", "One undoable cue edit", "Apply this row's validated draft only if its cue and loaded track identity are still current. Queue acceptance is not proof of application or a durable library save.", Dj;
    CueReload, "Reload cue values", "Discard editor drafts", "Replace the editor's name and color drafts with the currently applied cue values. This changes no audio, cue position or saved library data.", Dj;
    CueClose, "Close cue editor", "Discard unapplied drafts", "Close the cue list and discard fields that were not applied. Already applied cue positions, names and colors remain in the session and follow the library save status.", Dj;
    CueRelocate, "Relocate a library track", "Local file association", "Choose the new path, or search replacement folders, for the selected library track after a file move or copy. The worker must verify identical content before retaining the stable track identity and preparation.", Dj;
    CueRelocatePath, "Relocated track path", "Absolute local file path", "Enter the moved file's path. The original content must have been verified while available, or the original file must still exist. Filenames alone are never a match.", Dj;
    CueRelocateApply, "Verify and relocate track", "Background content verification and catalog save", "Compare complete file hashes and stable file metadata before changing the library association. Different bytes, an occupied destination or a changed source are rejected. Loaded and undo-retained old receipts preserve the same prepared identity. No files are moved or deleted.", Dj;
    RelocateRoots, "Replacement search folders", "1–64 absolute folders, one per line", "Search the selected track by complete content identity, including renamed files. A missing original needs its previously saved content digest. Symlinks and nested mounts are skipped; incomplete coverage is explicit. Changing these folders discards the previous review.", Dj;
    RelocateSearch, "Search replacement folders", "Background read-only discovery in Studio", "Compare up to 100,000 files, one million entries, 4,096 directories, depth 64 and 64 GiB of hashed bytes. Show up to 256 byte-identical copies without automatically choosing one. Cue and history saves remain available while searching. A newly measured original digest is saved before relocation becomes available.", Dj;
    RelocateCancel, "Cancel replacement search", "Leave track associations unchanged", "Cancel discovery cooperatively. Closing the relocation window or entering Performance protection also invalidates the search. Already committed catalog saves remain committed.", Dj;
    RelocateChoice, "Choose a replacement match", "Explicit location selection", "Review the full path of the copy you want. Several identical copies are ambiguous locations and require your choice. Incomplete searches may have additional unseen matches. Choosing a row alone changes no association.", Dj;
    RelocateUse, "Verify and use selected replacement", "Recheck identity and persist association", "Rehash the reviewed file and recheck its captured filesystem location before saving. Preserve stable track ID, preparation, crate membership and history. Replaced files and stale versions are rejected. A failed pre-rename save retains the old association; a completed rename with an unconfirmed directory sync is reported separately.", Dj;
    HotCue, "Hot cue", "Eight positions per deck", "An empty slot stores the current position; a filled slot jumps there. Shift-click or Delete cue in alternate actions removes it. Loading and preparation follow the exact source identity.", Dj;
    DeckEq, "Deck EQ", "Bass / mid / treble: 0–340% linear gain", "Drag to change the band's gain; click cuts the band, alternate action solos it. Center is unity; left/right channel histories are independent.", Mixing;
    DeckGain, "Deck gain", "0–120% linear gain", "Set the deck's level before mixing. Click or alternate actions can cut/solo the gain path. Zero is silent.", Mixing;
    SourceGain, "Track source gain", "Source trim in dB, separate from the fader", "Review whole-track RMS and sample peak. Auto uses an explicit target and peak limit with at most 12 dB boost. Manual keeps your override. Apply requires this loaded track to be stopped, untouched and settled; Cancel keeps the current trim. Analysis alone never changes playback gain. This is not LUFS or true-peak limiting.", Mixing;
    Platter, "Deck platter", "Playback / cue / jog", "Click toggles play/pause; right-click or Cue action returns to the main cue; Shift-click or Unload removes media. Drag while touching to scratch; release ends that touch. Keyboard/assistive actions expose the same operations.", Dj;
    Seek, "Deck waveform position", "0–source duration in seconds", "Seek within loaded media. Seeking resets grain history with a bounded transition; it does not change the stored file. A stopped deck stays stopped.", Dj;
    BeatJump, "Beat jump", "1/8–64 quarter-note beats; default 4", "Jump backward or forward by the displayed size without starting a stopped deck or changing its cue. Manual tempo anchors define the musical distance; otherwise use the source BPM. Active loops retain their bounds and wrap the destination within their musical span. Integer jumps preserve fractional beat phase except at file limits or when wrapping a non-integer loop. Bleep, roll and slip return clocks move by the same musical distance. Shift+[ / Shift+] jump on the selected deck; Alt+[ / Alt+] change its size. MIDI Learn exposes backward, forward, smaller and larger Note actions for either deck. Sizes remain for this launch across source loads; they are not saved preparation.", Dj;
    CueAudition, "Hold Cue audition", "Press / release; independent inputs", "From pause, Cue stores the current main cue and auditions while held. Release returns to that cue and pauses unless Play was pressed during the hold. While playing, Cue stops and returns; release does not restart. Repeated taps stutter from the cue. Hold the visible CUE button, focused Space/Enter or the deck's Cue shortcut (A/L by default). Assistive Click toggles a visible hold; Press/Release Cue actions are also available. MIDI Learn provides Deck hold Cue audition for Note On/Off; existing one-shot Deck set/return Cue remains available. Local and MIDI owners release independently. Focus loss, dialogs, source replacement and safety stops retire local holds. The command palette and platter's Cue action retain one-shot set/return behavior.", Dj;
    WaveformZoom, "Waveform zoom and phase", "2 / 4 / 8 / 16 four-beat bars", "Cycle each deck's span. Link uses one musical span for both decks. Native projects retain their own view; Save waveform view also retains it in the current preference profile after its save receipt. Without a grid, spans use source seconds. Beat and downbeat lines, eight-bar phrase counts, saved cues and loop boundaries use the loaded source's grid. Phase is the nearest signed beat difference against the selected deck, not automatic phrase detection. Output position estimate follows the audio output’s reported playback time. Unknown, expired or replaced media timing and key-lock or transition mixtures show renderer position explicitly. Display, converters and listening alignment remain unqualified.", Dj;
    DeckFilter, "Deck filter (mapped MIDI)", "−100% low-pass to +100% high-pass", "Center is exact bypass. Moving toward either edge attenuates more of the opposite spectrum. Smooth transitions preserve independent stereo histories.", Mixing;
    Crossfader, "Crossfader", "0% A to 100% B", "Blend the two decks. At or left of center A is favored for Match; right of center B is favored. This is independent of session track gains.", Mixing;
    DeckTime, "Deck time display", "Elapsed source seconds / remaining wall estimate", "Choose elapsed or estimated remaining time. Rate changes affect the remaining estimate; this is not a measured hardware output latency.", Dj;
    RunoutWarning, "Runout warning", "0–300 seconds; 0 disables", "Set a per-deck warning before file end. Repeating loops suppress the warning. The alert does not stop or switch the deck.", Dj;
    Quantize, "Quantize", "Deck on / off; 1/8 to 4 beats", "Toggle this deck's cue and loop quantization independently of session launches. Choose a division beneath the waveform. Queued onsets show their mapped beat and source time; release, scratch, stop or an input reset cancels them. Unprepared tracks use their source BPM. Settings last for this app launch.", Dj;
    LoopBounds, "Loop in / out", "Source positions", "Primary action sets loop in; right-click or Loop out action sets loop out. The loop needs a valid ordered region.", Dj;
    LoopEditor, "Loop editor", "64 source frames minimum; 1/8–64 beat presets", "Expand Loop editor below each platter. Edit exact source seconds, drag at one-source-frame precision, or nudge either edge one frame. The waveform shows the applied boundaries. Choose a fractional or multi-bar length, then Set loop length; this prepares the region without starting playback or enabling a stopped loop. Move by the selected beat increment while preserving the complete musical length through tempo anchors. Track edges shift the whole loop into range; an oversized or reversed region is refused. A changed source identity or a held roll/slice refuses the edit. Moves preserve the active playhead's relative musical position. Applied regions follow the existing preparation, project and Undo owners; size selectors are local drafts.", Dj;
    LoopDouble, "Double loop", "×2 duration", "Double the current loop region within source bounds.", Dj;
    LoopHalf, "Halve loop", "½ duration", "Halve the current loop region within source bounds.", Dj;
    Reloop, "Reloop", "Four bars when creating a loop", "Toggle the current loop; if none exists, create the supported four-bar region.", Dj;
    Match, "Match decks", "Effective beats per minute", "Match the unfavored deck to the favored deck's file BPM times pitch rate. If both play, align the unfavored phase. The favored position does not jump.", Dj;
    ComposeArm, "Arm compose target", "One track and scene cell", "Explicitly capture the selected cell as the pad-writing destination; an empty target becomes MIDI. Browsing does not retarget it. Arming itself does not play a note.", Recording;
    ComposeDisarm, "Disarm compose", "Armed / disarmed", "Finalize current pad captures and stop automatic pad writes. Existing monitor voices stay held until their own releases. Session Stop also disarms.", Recording;
    MidiFileImport, "Import Standard MIDI File", "SMF 0/1, PPQN 1–32767, 16 MiB", "Inspect notes, velocities, release velocities, channels, all channel messages, standard text, key, tempo and time signature events. Map tracks or split channels to session cells. Review unsupported omissions before import. Apply preserves source ticks and creates one guarded Undo entry.", Projects;
    MidiFileExport, "Export Standard MIDI File", "Source clip coordinates, SMF 0 or 1", "Select MIDI cells and an unused destination path. Export writes all selected clips at source beat zero, preserving trailing source silence. Choose muted-note inclusion and original or session conductor events. Clip loops, launch offsets and native mute flags are not SMF fields. Existing destinations produce an error.", Projects;
    MidiFilePath, "MIDI file path", "Regular local .mid or .midi file", "Read and write file bytes on the MIDI worker. Inspection detects source replacement; import uses the inspected contents only while that source remains current. Export uses an atomic exclusive file publication after successful encoding and synchronization.", Projects;
    MidiFileMapping, "MIDI track and channel mapping", "Up to 128 tracks by 512 scenes; 64 mapped/export clips per transaction; 8192 notes per clip, 65536 per session", "Choose every destination or disable a source row. Several source rows mapped to one cell combine there. Channel splitting attaches file-track metadata to its first row. Replace contents or explicitly merge existing MIDI clips; audio destinations fail before any change. Gains remain unchanged.", Projects;
    MidiFileTempo, "MIDI conductor choice", "Integer microseconds per quarter; meter denominators through 128", "Keep the current session conductor or use the complete file map. Conflicting simultaneous values require an authoritative file track. Applying a conductor supports 40–240 BPM and at most 4096 points of each kind; other values remain in original source metadata when keeping the session conductor. Metronome beats follow the meter denominator and accent each bar. A manual tempo edit resumes constant tempo and 4/4 and can be undone.", Projects;
    MidiFilePrecision, "MIDI tick precision", "PPQN 1–32767", "Original imported notes and events keep exact integer ticks. A different division or newly edited beat may require rounding. Exact export refuses unrepresentable values; allow nearest-tick rounding explicitly to accept at most half a destination tick per boundary. Export can refuse ambiguous overlapping same-channel/pitch note releases instead of changing durations.", Projects;
    MidiFileCancel, "Cancel MIDI file work", "Worker cancellation and atomic renderer claim", "Cancel inspection, preparation or encoding before publication. Cancel a queued import before the renderer claims it. After ownership or file publication wins, the actual completed result is reported. Close waits for pending work to settle.", Projects;
    PianoRoll, "MIDI piano roll", "Captured empty or MIDI clip", "Inspect the selected cell on the project worker. Drawing and numeric changes remain a draft until Apply. Browsing never retargets this editor. Every note has a stable identity and a virtualized accessible list entry.", Recording;
    MidiGrid, "MIDI timing grid", "Free, straight subdivisions or triplets", "Snap drawing and pointer movement to the selected quarter-beat subdivision. Free retains continuous pointer timing. Keyboard movement uses the grid, or 1/64 beat in Free. Numeric fields accept explicit values independently of snapping.", Recording;
    MidiNotes, "MIDI note actions", "Pitch 0–127; up to 8192 notes", "Draw on empty space; select a note, Shift-click to extend, drag its body to move or its right edge to resize. With Draw notes disabled, drag empty space for a rectangular selection. Arrows move or transpose; Shift+Left/Right resize; Ctrl+A selects all, Ctrl+D duplicates, M toggles mute and Delete removes. New and duplicate notes receive fresh IDs.", Recording;
    MidiValues, "MIDI note values", "Source quarter-note beats and velocity 1–127", "Enter pitch, start, length, velocity and mute. Add note creates a new identity; Set selected note values applies these values to each selected note while retaining its identity. Movement buttons change selected positions relatively.", Recording;
    MidiStep, "MIDI step entry", "Stopped transport; quarter-note, straight or triplet steps", "Choose a step duration and the visible cursor. Insert cursor pitch, advance with a held chord, rest, tie the previous chord or delete the last step. Enable Computer musical keyboard and focus its input button: A W S E D F T G Y H U J K play C through C; Z/X change octave; C/V change velocity; Space advances, Shift+Space ties and Backspace deletes. Record steps on key release inserts a complete chord when its last key is released. Repeats are ignored; focus loss, text entry, Apply and closing release audition notes. Apply commits the draft as one Undo entry.", Recording;
    MidiRhythm, "Rhythm generation", "Up to eight voices, 64 steps per voice and 8192 notes", "Set each voice's pitch, independent steps and duration, pulses, rotation, density, velocity and accent interval. Swing and gate use fractions: 0.2 swing delays odd steps by 20% of one step; 0.5 gate holds for half a step. Density 0 is empty and 1 retains all pulses. The exact integer seed makes variations repeatable. Preview spans the least-common loop, keeps existing notes unless Replace draft notes is selected, and writes ordinary editable notes. Restore works until preview notes or loop bounds are edited; Apply commits one Undo change. Common periods above 262144 beats or 65536 generated steps are refused. Timing stays in quarter-note beats through meter or scale changes; pitches remain explicit.", Recording;
    MidiRegion, "MIDI clip and loop bounds", "0–262144 source quarter-note beats", "Set clip start/end and loop start/end numerically or drag the distinct ruler markers. Start must not exceed loop start; loop end must not exceed clip end. Minimum span is 1/1024 beat. Intro notes play once; looping repeats its active region and gates close at explicit boundaries. Very dense short loops are rejected.", Recording;
    MidiView, "MIDI pitch and time view", "Pitch/time rulers, folding, zoom and scroll", "Time scroll chooses the first visible source beat; Top pitch chooses the highest visible pitch. Zoom changes pixels per beat or pitch. Used/major/minor folding keeps existing off-scale notes visible. Hidden notes remain selectable in the native note list.", Recording;
    MidiApply, "Apply MIDI edit", "One guarded session History transaction", "Commit this captured draft only if its original MIDI content and project epoch still match. Active recording into the target, stale work, performance protection or unavailable History reject the request and retain the draft. Wait for the renderer outcome. Applied changes persist through native project Save and Undo/Redo.", Recording;
    MidiAudition, "MIDI note audition", "Independent non-recording voice", "Audition the note value through the captured track. Stop note audition, focus loss or close releases its own gate without releasing other physical notes. Drum one-shots retain their natural decay. Performance protection excludes new audition presses but accepts releases.", Recording;
    MidiCancel, "Cancel or close MIDI editor", "Explicit draft discard and pending cancellation", "Cancel/Escape and application Close preserve unapplied work until Keep editing or Discard. A pending Apply can be cancelled before renderer ownership; an already claimed edit completes and remains in History. Unconfirmed disconnected outcomes remain visible.", Recording;
    SamplerEdit, "Edit sampler banks", "Captured project bank", "Open a draft of the selected working bank. Factory originals are read-only: copy before editing. Later selection, Undo or project replacement never retargets an existing draft.", Recording;
    SamplerName, "Sampler bank name", "1–128 UTF-8 bytes for reusable definitions", "Working draft and reusable-save names are separate. Renaming does not replace another definition with the same name.", Recording;
    SamplerCreate, "Create empty bank", "Sixteen empty slots", "Prepare a new working-bank identity off the audio thread. It remains a preview until Apply; empty slots never receive default sounds.", Recording;
    SamplerCopy, "Copy sampler bank", "New working identity", "Copy immutable audio and controls into a new editable draft. Original Kit / Perc / Hits buttons remain available even after a project replaced the startup banks. Original banks and held voices keep their captured sources.", Recording;
    SamplerSlot, "Sampler slot", "Slots 1–16", "Choose the slot to inspect or edit. Changing the selected slot stops the independent audition; pad input remains separate.", Recording;
    SamplerAssign, "Assign selected local source", "Exact crate source and file version", "Capture the selected local-file or mounted removable-volume identity and decode it on the bounded shared worker. Changed or invalid media is rejected without replacing the current bank. Built-in deck stems are not file assignments.", Recording;
    SamplerClear, "Clear sampler slot", "Prepared edit", "Prepare an empty slot. Apply is required before pads change; clearing never substitutes a factory sound.", Recording;
    SamplerRetry, "Retry sampler source or store", "Explicit worker retry", "Retry the referenced missing source or reopen the reusable store. Source identity must still match or have a verified library relocation; unrelated files are not substituted.", Recording;
    SamplerPlayMode, "Sample slot play mode", "Trigger / Hold / Toggle", "Trigger restarts at the cue on every press and continues after release. Hold stops when the final input is released. Toggle stops on the next press. A sounding slot retains its captured mode across bank changes and edits.", Recording;
    SamplerRepeat, "Repeat sample slot", "On / off", "Repeat wraps from the exclusive source endpoint to the captured cue or trim start. Hold release, Toggle press and Stop slot end repeat. Prepare and Apply change future onsets.", Recording;
    SamplerCue, "Sample slot cue", "Source seconds; blank uses trim start", "Cue must be inside the prepared source range. Trigger and retrigger start at this point; repeating slots wrap back here. Preparing an invalid cue preserves the installed bank.", Recording;
    SamplerSlotStop, "Stop sample slot", "Exact slot; reserved admission", "Stop the sounding sample or synth pad without stopping other slots or transport. Right-click a pad or press Shift+Escape while it has focus. The editor stops its selected slot; MIDI learn assigns an exact slot button. Release a physically held input before triggering again.", Recording;
    SamplerGain, "Sampler slot gain", "0–2 linear", "Gain is captured at audition or pad onset. Prepare preview and Apply to change future pads; held voices retain their original gain.", Recording;
    SamplerTrim, "Sampler source range", "Start inclusive / end exclusive in source seconds", "Blank end uses the source end. Start must precede end within the decoded source. Prepare validates the range; source seconds are independent of output sample rate.", Recording;
    SamplerPreview, "Prepare sampler preview", "Worker validation", "Validate controls and register immutable audio off the renderer. A ready preview changes neither the working bank nor its physical gates.", Recording;
    SamplerAudition, "Audition sampler slot", "One independent voice", "Play the prepared range and gain through the captured selected track. This does not press a sampler pad or record a note. Existing mix/effect controls still affect output.", Recording;
    SamplerAuditionStop, "Stop sampler audition", "Reserved release", "Stop the exact audition identity. Cancel, slot changes and replacement also request this release; admission failures remain visible and retry.", Recording;
    SamplerDefinition, "Reusable sampler definition", "Stable definition identity", "Choose a saved reference definition. Selection alone changes no working bank; Import prepares sources and reports unavailable slots explicitly.", Recording;
    SamplerImport, "Import reusable sampler bank", "Local reference resolution", "Prepare a new working identity from the selected definition. Missing or changed files stay missing with diagnostics. Apply is separate; native projects embed playable audio.", Recording;
    SamplerOverwrite, "Replace reusable definition", "Explicit selected identity", "Allow Save reusable to overwrite the selected definition ID. Matching a name alone never authorizes replacement.", Recording;
    SamplerSave, "Save reusable bank", "Reference file / explicit replacement", "Persist the prepared draft as a named reusable definition. This does not Apply a working bank or save the native project. Reusable banks retain file identities, controls and ranges, not copies of local PCM.", Recording;
    SamplerApply, "Apply sampler bank", "One revision-qualified undoable edit", "Queue the prepared bank for its original project epoch and bank revision. Wait for renderer Applied: admission is not completion. Cancellation can win only before renderer claim.", Recording;
    SamplerCancel, "Cancel sampler editor", "Stop audition and discard unapplied draft", "Cancel pending preparation and request audition release. Applied edits and committed reusable saves survive closing. An already claimed Apply reports its actual outcome.", Recording;
    SamplerWaveform, "Sampler waveform", "Source peaks and frequency energy", "Display prepared stereo peak envelopes with left above and right below, plus range markers. Red represents bass, followed by orange, yellow, green, cyan, blue and violet toward treble. Overlapping frequency bands are measured at the source sample rate. Detail follows screen pixels and preserves narrow transients. Legacy samples without detailed analysis use the sampled PCM preview.", Recording;
    SamplerBank, "Sampler bank", "Working banks; original Kit / Perc / Hits", "Choose a working bank of sixteen slots. Edit banks creates, copies or imports reusable banks. New pad presses use the new bank; held voices retain their captured source.", Recording;
    SamplerInstrument, "Sampler instrument", "Samples / Analog / Keys / Pad", "Choose the source for new pad presses. Synth choices have distinct sound/envelopes; held voices keep their original instrument. Drums remain sample banks, not a separate synth choice.", Recording;
    SamplerOctave, "Sampler octave", "C1–C7; steps of 12 semitones", "Transpose held instrument notes by an octave; sample rate changes by powers of two around octave 3. Matching releases retain the original input identity.", Recording;
    SamplerPad, "Sampler pad", "Sixteen sample identities / thirteen piano keys", "Press holds a gate; release stops it, including outside the cell. Space/Enter hold the focused pad; assistive click toggles hold. Sample pads are 9–16 above 1–8; blank piano cells are inert. Armed compose writes one captured note.", Recording;
    LibraryLayouts, "Library layouts", "Named layouts in the active profile", "Edit columns, density and ordering. Preview changes the browser locally. Save layouts writes through the preference owner; a busy or dirty Preferences draft must be finished first. Discard restores the saved profile. Copy uses a distinct name; Delete keeps at least one layout.", Dj;
    LibraryColumns, "Library columns", "Visibility, order and width in points", "Show or hide any column while keeping at least one visible. Move a column with its arrows and resize it from 36 to 1024 points. Header and row cells share horizontal scrolling and clip long text to their own column.", Dj;
    LibrarySort, "Library sorting", "Primary and secondary metadata order", "Choose a primary and a different secondary column, with independent directions. Click a header for primary sorting; Shift-click sets secondary sorting. Missing metadata remains last, equal values preserve published/manual order, and Unicode text is compared without case differences. Manual order restores direct saved crate membership. Source selection and viewport anchors survive sorting.", Dj;
    LibraryDensity, "Library density and artwork", "Compact, Comfortable or Artwork rows", "Compact retains small rows; Comfortable adds space; Artwork shows embedded PNG/JPEG covers for visible scanned local sources. One bounded worker reads source-version-checked pictures; previews retain a bounded cache. Missing, unsupported or failed artwork is reported. Reads pause under protection; artwork never substitutes for source identity.", Dj;
    CrateSearch, "Search crate", "Text filter · AND terms and explicit fields", "Combine ordinary words or quoted field values with AND. Text fields: title, artist, key (exact), tag (exact), group and note. Use bpm:120..128, bpm>=120, length:3:00..4:00, rating>=4, played:yes/no or color:#RRGGBB. Length also accepts seconds; ranges include both ends. Unknown fields and malformed values show an error and no results. Played means renderer-confirmed playback of the current source/version. Text editing owns its keys; filtering never changes loaded media.", Dj;
    CrateSearchScope, "Search all library", "Current crate / whole library", "Broaden the current query without changing the named crate. Returning restores that crate's saved query, selected source and scroll. Changing the selected crate deliberately discards the old return context. This switch changes only library navigation.", Dj;
    CrateScan, "Scan library", "Background filesystem discovery", "Scan configured watched folders with bounded traversal. Known removable roots resolve by UUID even at a new mountpoint; an offline volume is not a deleted file. Readable supported entries publish together; skipped reasons and incomplete coverage are visible. Cancellation keeps the prior crate, and the persistent catalog retains saved identities absent from a scan.", Dj;
    CrateCancel, "Cancel scan", "Pending operation", "Request cancellation and retain the existing crate. An in-progress filesystem call finishes before cancellation is acknowledged.", Dj;
    CrateRow, "Crate row / selection", "Filtered row number", "Select with click or focused Up/Down/Page/Home/End. Double-click or Enter loads the selected deck; alternate actions choose A or B. BPM provenance, duration and history describe the exact source.", Dj;
    DeckSelect, "Selected deck", "A / B", "Choose the destination for F, Enter and controller Load selected. Explicit →A/→B always use their named deck. Browsing later does not redirect an already accepted load.", Dj;
    DeckLoad, "Load selected crate source", "Deck A / B", "Request the captured source on the named deck. Queued/decoding are not Loaded; wait for renderer confirmation. Failures retain existing media. Built-in stems bypass file decoding.", Dj;
    SessionLayout, "Edit session layout", "128 tracks, 512 scenes; worker preparation and bounded Undo", "Create audio/MIDI tracks and scenes; rename, reorder by display position, choose RGB colors, duplicate or delete. Go to track and Go to scene reveal any active cell, including offscreen rows and columns. All controls accept keyboard and assistive actions. Reorder preserves playing clips, automation, compose targets and stable controller slots. Duplicates share immutable embedded audio and copy notes/settings with fresh IDs, starting stopped. Delete ends that target's captures and voices; Undo restores content without inventing a held key or restarting playback. Limits are 65536 session notes, 8192 per clip, 16 MiB MIDI lanes, 64 MiB native metadata and 256 MiB prepared effect buffers, plus existing PCM/edit/undo budgets. A refused or cancelled edit preserves current work. MIDI routing Apply/Retry attaches a route to the current track identity after deletion/reuse or project change.", Editing;
    Track, "Track header", "Up to 128 tracks", "Click toggles mute; right-click or alternate actions toggle solo. Alternate actions also select the track or open its effect rack. Muted playback keeps advancing.", Mixing;
    TrackGain, "Track gain", "0–120% linear gain", "Adjust track output level. Click toggles mute; right-click toggles solo; Control-click or alternate action opens effects. Held source ownership does not move with selection.", Mixing;
    Scene, "Scene launch", "Up to 512 scene rows", "Primary action launches or stops the scene; Shift adds its clips alongside other scenes; right-click restarts. Alternate actions expose the same choices and the scene effect rack.", Mixing;
    Clip, "Clip cell", "Track × scene", "Click launches once; right-click launches looping. Shift-click explicitly arms composition; Alt-click opens gain. Shift+F10 exposes named actions. Queued launch is distinct from playing.", Recording;
    ClipGain, "Clip gain", "0–150% linear gain", "Change gain for future note onsets. Already held synth/sample notes retain their onset gain; track gain still affects the whole output.", Editing;
    FxAdd, "Add effect", "Track or scene rack", "Add the named implemented processor to the current rack. Arp is available only on a MIDI track's upstream events, not a scene audio bus. Capacity rejection is explicit.", Mixing;
    FxToggle, "Effect enabled", "On / off", "Enable or bypass this slot with a bounded 5 ms transition. Arp changes MIDI event scheduling rather than blending audio.", Mixing;
    FxParameter, "Effect parameter", "Per-effect displayed units and range", "Each slider names its implemented DSP control. The detailed label, current value and tooltip come from the same DSP metadata. Delay time is fixed at 250 ms; Arp has only enable/bypass.", Mixing;
    FxClose, "Close effect rack", "View only", "Return to the clip grid without removing or bypassing the rack's effects.", Mixing;
    MasterFxSelect, "Master effect type", "Echo → Reverb → Filter", "Cycle this stereo master slot's processor. Filter is a fixed 1 kHz low-pass. Each slot has independent left/right histories.", Mixing;
    MasterFxWet, "Master effect wet", "0–100%", "Blend dry and processed output for this master slot. Zero preserves dry audio; 100% selects processed output.", Mixing;
    Midi, "MIDI connections", "Port status and input counters", "Open the MIDI window to inspect actual connection state, queue/drop/reset counters and per-port errors. Device names alone do not prove mapping or hardware behavior.", Controllers;
    MidiLearn, "MIDI learn", "256 exact-port assignments; one captured gesture", "Choose a performance action, target and compatible message type. Relative encoders require an explicit format and sensitivity. Capture consumes one gesture for review; unrelated controls retain their mapping. Conflicts require Replace. Test submits the captured action through ordinary control admission. Add/Replace/Edit/Remove affect this run; Save MIDI assignments retains the active profile after its durable preferences receipt. Remove restores any built-in action. Cancel, close, timeout and disconnect end learning; existing assignments remain. Input changes release older source gates and fence stale queued messages. Missing exact ports remain unavailable until recaptured.", Controllers;
    MidiPresets, "MIDI mapping presets", "32 named factory overlays per profile; 256 active assignments", "Save a selected exact port's learned overrides as a named definition. Duplicate, rename, delete or export definitions without changing active assignments. Portable version 1 JSON omits backend port IDs; Import validates the entire file for explicit review and bank save. A conflicting name needs a new name. Review load or factory defaults for one unique connected exact port; Apply checks its config revision, source owner and active profile again. Reconnects and other edits require fresh review. Unlisted factory controls and other port assignments remain intact. Save MIDI assignments persists the applied layer; bank save alone does not activate it. All file work is cancellable and owned by Preferences. A failed save retains previous settings and live assignments.", Controllers;
    MidiRetry, "Retry / rescan MIDI", "Background connection request", "Discover current ports and retry the requested input policy, then rescan saved output routing. Vanished outputs reset/retire and remain unavailable until an exact reconnect. No automatic hotplug detection is claimed. Busy means work is pending; missing/failed ports remain explicit. Keyboard and mouse remain available.", Controllers;
    ProjectMenu, "Project menu", "Native .omat documents", "Create, save or open a document. New/Open/Close protect unsaved work and restore playback stopped.", Projects;
    ProjectNew, "New project", "Empty session", "Replace the document with an empty session and factory sampler resources only after the unsaved-work decision. Use Cancel to keep working.", Projects;
    LiveSetOpen, "Next live set", "One staged native project", "Preload and cue the next set while the current performance continues. Review its path, cue position, fade and unsaved-work decision before transition.", Projects;
    LiveSetPath, "Next live set path", "Native .omat file", "Choose an embedded native project for bounded preflight. The current graph remains active; missing audio and unavailable processors refuse preload.", Projects;
    LiveSetPreload, "Preload next set", "One project; 256 MiB PCM", "Validate embedded audio and prepare processors on a background worker. Standard stereo master routes are required. Leave performance protection deliberately before preloading.", Projects;
    LiveSetCue, "Cue next set", "Outputs 3/4 on the current device", "Listen to the next set through a separate stereo pair without changing the outgoing master. At least four output channels are required. Cue starts remembered clips and loaded decks and holds its position when stopped.", Projects;
    LiveSetFade, "Live-set fade seconds", "0.01 to 30 seconds", "Choose a linear sample-by-sample fade between both complete renderer graphs. Active outgoing decks and effect histories continue until the fade finishes.", Projects;
    LiveSetDiscard, "Discard current unsaved edits at transition", "Explicit current-document decision", "Allow the transition to retire unsaved current work. Save the current project first if you need those edits; preload itself does not discard them.", Projects;
    LiveSetTransition, "Transition to next set", "Reviewed current revision", "Commit the ready set at the next admitted audio block. Continue from its cue position, fade the outgoing graph and retire its storage on the worker. Recording, changed state and protected mode refuse it.", Projects;
    LiveSetCancel, "Cancel next set", "Before renderer commit", "Cancel preload or staging while preserving the current performance. A committed transition completes and cannot be undone by this button. Safety stop or silence remains authoritative.", Projects;
    ProjectOpen, "Open project", "Native .omat file", "Read and validate a project off the UI/audio thread before replacing the current document. Failed or unsupported files preserve the current session.", Projects;
    ProjectRecent, "Recent projects", "Local paths", "Open a previously successful project path with the same validation and unsaved-work protection as Open. A listed path may no longer exist.", Projects;
    ProjectSave, "Save project", "Current .omat path", "Save a coherent renderer capture. Edits made after capture remain unsaved. An error does not mark the document clean.", Projects;
    ProjectSaveAs, "Save project as", "New current .omat path", "Choose a destination and make it current after successful save. Explicit replacement permission is required for an existing destination.", Projects;
    ProjectSaveCopy, "Save copy", "Independent .omat destination", "Write a copy without changing the current project path or clean/dirty baseline.", Projects;
    ProjectPath, "Project path", "Absolute or working-directory-relative path", "Enter the local native project destination or source. No network upload occurs. Cancel preserves the current document.", Projects;
    ProjectReplace, "Replace existing project file", "Explicit overwrite permission", "Permit replacement of this chosen destination for Save as/Copy. The file is staged and committed atomically; rejected saves preserve the previous file.", Projects;
    ProjectDiscard, "Discard unsaved changes", "Destructive document decision", "Authorize this pending New/Open/Close without saving the current unsaved work. This is not an undo-history operation.", Projects;
    ProjectCancel, "Cancel project operation", "Pending dialog or worker", "Keep the current document by cancelling the pending decision/operation before commit. A commit already completed is reported as completed, not undone.", Projects;
    Undo, "Undo", "Previous named creative transaction", "Restore the previous recorded creative edit while preserving unrelated transport and input gates. Availability is renderer-confirmed, bounded and separate from queue admission.", Editing;
    Redo, "Redo", "Next named creative transaction", "Reapply the next recorded edit. A new edit clears the redo branch. Rejected history operations leave a visible reason.", Editing;
    History, "Edit history", "Bounded named transactions", "Inspect applied/redo entries, target context and memory accounting. Continuous gestures group; unsupported future features are not represented.", Editing;
    HistoryDismiss, "Dismiss history message", "Message only", "Clear the renderer's history notice. It does not retry a rejected edit or recover evicted history.", Editing;
    BackgroundJobs, "Background jobs", "Shared worker limits", "Inspect queued and running decode, analysis, indexing, rendering and provider work. At most two optional workers and one audio decoder share 3 GiB of declared active-worker reservations. Existing prepared media and caches have separate limits. Worker CPU and disk priorities are lowered on Linux. A finished worker is not proof of renderer application or a completed save.", Setup;
    BackgroundCancel, "Cancel captured job", "One stable request identity", "Request cooperative cancellation for this exact queued or running job. Reused worker slots and newer requests are not targeted. A filesystem read already in progress may finish before cancellation is observed. Already committed writes retain their actual outcome in the original workflow.", Setup;
    Diagnostics, "Audio diagnostics", "Measured CPU, wall time, queues and sampled load", "Inspect callback elapsed time/deadlines separately from render-thread CPU, UI update time and reported output latency. Backend XRUN count remains unavailable when the backend supplies none.", Emergency;
    DiagnosticCapture, "Start diagnostic capture", "Bounded local sample report", "Capture measured counters and sampled render cost with bounded storage. No project audio or personal media paths are exported.", Emergency;
    DiagnosticStop, "Stop diagnostic capture", "Capture state", "Finish collecting diagnostic samples and keep the captured report for review/export. Audio playback is unchanged.", Emergency;
    DiagnosticCancel, "Cancel diagnostic operation", "Capture or file worker", "Cancel the pending capture/file operation. The audio engine is unaffected; an already committed file is reported honestly.", Emergency;
    DiagnosticFileCancel, "Cancel diagnostic file operation", "Pending worker", "Cancel the pending report export or reopen before commit. A file already committed is reported as completed; live audio is unchanged.", Emergency;
    DiagnosticPath, "Diagnostic file path", "Local JSON path", "Choose a local destination/source for a redacted diagnostic report. Export refuses an existing destination instead of overwriting it.", Emergency;
    DiagnosticExport, "Export redacted diagnostics", "Local JSON file", "Write the bounded captured report on a worker. Wait for exported confirmation; no upload or automatic sharing occurs.", Emergency;
    DiagnosticReopen, "Reopen diagnostic capture", "Validated local JSON file", "Read a prior report for inspection without changing the live engine. Invalid/oversized reports are rejected.", Emergency;
    Library, "Library catalog", "Persistent preparation and media identity", "Inspect catalog save status or import an Omatainer catalog. The library is separate from native projects and never substitutes another file's preparation by path alone.", Dj;
    LibraryBackup, "Back up and restore DJ library", "Complete independent catalog snapshot", "Export a fixed saved catalog, optionally collect authorized local tracks, verify a backup and restore into a new directory. Import is explicit and rejects conflicts before changing the live catalog.", Dj;
    LibraryBackupPath, "Library backup paths", "Absolute local directories", "Choose a new directory for export or restore and an existing backup for verification. Existing destinations are never replaced. Restore must remain outside the read-only backup.", Dj;
    LibraryBackupCollect, "Authorized local music collection", "1–1024 GiB total; 8 GiB per file", "Explicitly authorize copying all local current catalog tracks. Encoded bytes and source identities are verified. Duplicate bytes share a backup asset; provider music is not collected. Originals remain read-only.", Dj;
    LibraryBackupExport, "Export library snapshot", "Saved catalog and optional collected music", "Wait for the catalog owner to finish saving. The captured snapshot stays fixed during later edits. Cancellation and protection prevent incomplete publication.", Dj;
    LibraryBackupRestore, "Verify and restore library", "Versioned metadata and SHA-256 media checks", "Verify the complete backup before restoring preparation, identities, crates, favorites and history into a new directory. Each restored track keeps its own pathname; no catalog activates automatically.", Dj;
    LibraryBackupCancel, "Cancel library backup job", "Bounded worker cancellation", "Stop optional backup reads and discard uncommitted private staging. A completed publication reports its actual durability outcome. Closing the window alone does not cancel the job.", Dj;
    LibraryImportPath, "Catalog import path", "Local Omatainer catalog JSON", "Enter the catalog to validate and merge. This does not import arbitrary third-party library formats.", Dj;
    LibraryImport, "Import catalog", "Validated background merge", "Merge compatible identities and preparation off the UI thread. Malformed/newer/conflicting data is rejected; unrelated pending edits remain preserved.", Dj;
    MusicImportPaths, "Music paths", "Explicit file and folder inputs", "Enter one absolute local music file or folder per line. The background worker reads at most 64 inputs, 64 folder levels, one million entries and 100,000 library rows. Unsupported, unreadable and truncated entries have visible reasons.", Dj;
    MusicImport, "Import music files/folders", "Background music discovery", "Wait for the current catalog save, then merge readable audio files/folders without unloading either deck. Overlapping inputs are deduplicated; mounted removable media keeps UUID/relative-path identity. Cancellation before publication keeps the prior crate.", Dj;
    MusicRoots, "Manage music folders", "Saved library root preferences", "Open Preferences to edit and apply watched music folders. After a scan, changes coalesce on the filesystem worker; a full-scan hint every 30 idle seconds covers missed notifications. Scans wait for Studio and current catalog work; filesystem work can delay completion. Known volumes reconnect by UUID; offline or ambiguous media stays explicit. Removing a root deletes only its bookmark, never tracks or audio.", Dj;
    LibraryRetry, "Retry library save", "Persistent preparation", "Retry a failed catalog publication. Keep the visible failure until durable saving is confirmed.", Emergency;
    LibraryCloseWithoutSaving, "Close without saving library", "Explicit data-loss decision", "Exit despite unsaved library preparation after a save failure. Keep working or Retry preserves a chance to save it.", Emergency;
    License, "Licenses and notices", "Installed build records", "Read bundled notices for this build offline. The native manifest identifies the packaged components and exact source records.", Setup;
    LicenseSearch, "Search license notices", "Text filter", "Filter local component/notice entries. No network lookup occurs.", Setup;
    LibraryKeepWorking, "Keep working", "Cancel pending exit", "Cancel the pending close while library saving is pending or failed and return to the current document. Unsaved library edits remain available for retry.", Emergency;
    LicenseSource, "Notice source link", "External upstream URL", "Open the recorded upstream source in your browser. This leaves the offline viewer; the bundled notice remains available without network access.", Setup;
    LicenseNotice, "Full license notice", "Bundled text", "Expand the complete license or attribution text recorded for this build. Reading does not change audio or project state.", Setup;
    LicenseEntry, "License entry", "Component record / notice text", "Select or expand a bundled notice to read its attribution and terms.", Setup;
    LoadRetry, "Retry media load", "Captured source and destination", "Retry the failed source on its original deck. Later crate selection does not redirect Retry. Existing playing media stays until accepted replacement is applied.", Dj;
    LoadDismiss, "Dismiss media status", "Message only", "Hide this load status. It does not unload the deck, cancel playback or discard an already rendered play-history event.", Dj;
}

pub fn manual() -> String {
    let mut text = String::from("# Omatainer offline manual\n\nGenerated from the in-app help catalogue. Hardware observations remain separate from software confirmation.\n\n");
    for topic in Topic::ALL {
        text.push_str(&format!("## {}\n\n{}\n\n", topic.title(), topic.text()));
        if !super::lessons::steps(topic).is_empty() {
            text.push_str("Guided example (use Start this lesson in Help; Next requires observed evidence):\n\n");
        }
        for (index, step) in super::lessons::steps(topic).iter().enumerate() {
            text.push_str(&format!("{}. {}\n", index + 1, step));
        }
        text.push_str("\n");
    }
    text.push_str("## Control reference\n\n");
    for &control in Control::ALL {
        let d = control.definition();
        text.push_str(&format!(
            "### {}\n\n{}\n\n{}\n\nWorkflow: {}.\n\n",
            d.title,
            d.units,
            d.purpose,
            d.topic.title()
        ));
    }
    text.push_str("## Shortcut reference\n\nThe in-app Help window shows the active bindings. Defaults follow; text fields and dialogs own their keys before performance shortcuts.\n\n");
    for b in super::super::shortcuts::BINDINGS {
        text.push_str(&format!("- {}: {}\n", b.label, b.description));
    }
    text
}
